 if (assets.length == 0 || assets[assetsIndex[_tigAsset]] == address(0) || totalSupply() == 0 || !_allowedAsset[_tigAsset]) return;
 try IERC20(_tigAsset).transferFrom(_msgSender(), address(this), _amount) {
