​
 function test_selfLiquidation() public {
​
 // malicious user borrows at max leverage + some safety margin
        uint256 margin0 = 51e18 + 1000e18;
        uint256 borrows0 = 10000e18;
​
 deal(address(asset0), address(account), margin0);
