        emit log_named_uint("Liquidated User borrow:", lender0.borrowBalance(address(account)));
        emit log_named_uint("Liquidated User assets:", asset0.balanceOf(address(account)));
    }
​
 enum Action {
 WITHDRAW,
 BORROW,
 UNI_DEPOSIT
    }
​
 // IManager
