Users can abuse the public
UTB:receiveFromBridge
function's lack of access control to directly call the internal
UTB:_swapAndExecute
function.
This bypasses the
UTB:retrieveAndCollectFees
modifier, which is used to collect fees from UTB users and validate fee and swap instructions via
UTBFeeCollector:collectFees
in all other public swap/bridge functions (namely
UTB:swapAndExecute
and
UTB:bridgeAndExecute
).
This allows users to execute inter-chain swaps without spending bridge fees, using instructions that have not been signed by a validator key. Unsigned additional payloads can also be included in the swap instruction's
payload
element, which would then be executed by the
UTBExecutor:execute
function.
Root Cause
Missing access control in
UTB:receiveFromBridge
UTB:receiveFromBridge
is likely missing an access control modifier.
Note that the missing modifier may not be the [
UTB:retrieveAndCollectFees
] modifier, as this modifier is understood to be intended for checking the UTB swap/bridge instructions on the source chain. Refer to the remedial suggestions for an alternate means of access control.
UTB:receiveFromBridge
----new code block----
​
//File:src/UTB.sol
​
contract UTB is Owned {
​
    ...
​
 function receiveFromBridge(
        SwapInstructions memory postBridge,
 address target,
 address paymentOperator,
 bytes memory payload,
 address payable refund
    ) public { // missing retrieveAndCollect modifier
        _swapAndExecute(postBridge, target, paymentOperator, payload, refund);
    }
​
    ...
​
 // if a feeCollector has been set, then this modifier validates the fee struct against the signer:
​
 modifier retrieveAndCollectFees(
        FeeStructure calldata fees,
 bytes memory packedInfo,
 bytes calldata signature
    ) {
 if (address(feeCollector) != address(0)) {
 uint value = 0;
 if (fees.feeToken != address(0)) {
                IERC20(fees.feeToken).transferFrom(
 msg.sender,
 address(this),
                    fees.feeAmount
                );
                IERC20(fees.feeToken).approve(
 address(feeCollector),
                    fees.feeAmount
                );
            } else {
                value = fees.feeAmount;
            }
            feeCollector.collectFees{value: value}(fees, packedInfo, signature);
        }
 _;
    }
​
    ...

 // swapAndExecute/bridgeAndExecute functions both validate fees/instructions signatures via retrieveAndCollectFees modifier
​
 function swapAndExecute(
        SwapAndExecuteInstructions calldata instructions,
        FeeStructure calldata fees,
 bytes calldata signature
    )
 public
 payable
        retrieveAndCollectFees(fees, abi.encode(instructions, fees), signature)
    {
        _swapAndExecute(
            instructions.swapInstructions,
            instructions.target,
            instructions.paymentOperator,
            instructions.payload,
            instructions.refund
        );
    }
​
 function bridgeAndExecute(
        BridgeInstructions calldata instructions,
        FeeStructure calldata fees,
 bytes calldata signature
    )
 public
 payable
        retrieveAndCollectFees(fees, abi.encode(instructions, fees), signature)
 returns (bytes memory)
    {
        (
 uint256 amt2Bridge,
            BridgeInstructions memory updatedInstructions
        ) = swapAndModifyPostBridge(instructions);
 return callBridge(amt2Bridge, fees.bridgeFee, updatedInstructions);
    }
​
    ...
​
 // _swapAndExecute directly bypasses any signature/fee checks before the swap/payload is executed.
​
 function _swapAndExecute(
        SwapInstructions memory swapInstructions,
 address target,
 address paymentOperator,
 bytes memory payload,
 address payable refund
    ) private {
        (address tokenOut, uint256 amountOut) = performSwap(swapInstructions);
 if (tokenOut == address(0)) {
            executor.execute{value: amountOut}(
                target,
                paymentOperator,
                payload,
                tokenOut,
                amountOut,
                refund
            );
        } else {
            IERC20(tokenOut).approve(address(executor), amountOut);
            executor.execute(
                target,
                paymentOperator,
                payload,
                tokenOut,
                amountOut,
                refund
            );
        }
    }
​
}
