 711:         require(coin != asset);
 712:         if (maturity != MATURITY_NOT_SET) {
 713:             require(coin != ERC20(address(yt)) && coin != pt && coin != ERC20(address(space)));
 714:         }
 715:         coin.transfer(rewardRecipient, coin.balanceOf(address(this)));
 716:     }
​
​
