 function _withdraw(
 address caller,
 address receiver,
 address owner,
 uint256 assets,
 uint256 shares
        ) internal virtual {
 //@audit @3.1 -- To exploit the vulnerability, Bob must approve the shares transfer of the 'owner' account 
 //               for the withdrawer account (i.e., msg.sender).
