 // ...
        PoolType::Trade => match self.bonding_curve {
            BondingCurve::Linear => self.spot_price
                .checked_add(self.delta)
                .checked_sub(self.delta)
                .map_err(|e| ContractError::Std(StdError::overflow(e))),
 // ...
        },
    }?;
 // ...
}
