Description
The
DelegatedStaking
contract implements the
claimReward()
function used by delegators to claim their rewards:
----new code block----
function claimReward(address payable owner) external {
    (uint256 totalToClaim, ClaimData[] memory claimDetails) = calcReward(owner);
 if(totalToClaim == 0) {
 revert NothingToClaim();
    }
 //transfer reward
    owner.transfer(totalToClaim); // <-----------------------------
 //update last claimed epoch
    lastClaimedEpochForAddress[owner] = claimDetails[claimDetails.length - 1].epochNumber; // <---------------
 emit Claim(signPublicKey, forgerVrf1, forgerVrf2, owner, claimDetails);
}
----end of code block ----
As we can see in the code above, the check-effects-interactions pattern is not respected as the Eon transfer(interaction) is performed before the update of the
lastClaimedEpochForAddress
state variable(effect). This could cause some reentrancy risks (which are partially mitigated by the 2300 gas limit of the
transfer()
function).
BVSS
AO:A/AC:L/AX:L/C:N/I:M/A:N/D:N/Y:M/R:N/S:U (6.3)
Recommendation
It is recommended to update the
DelegatedStaking.claimReward()
function as shown below:
----new code block----
function claimReward(address payable owner) external {
    (uint256 totalToClaim, ClaimData[] memory claimDetails) = calcReward(owner);
 if(totalToClaim == 0) {
 revert NothingToClaim();
    }
 //update last claimed epoch
    lastClaimedEpochForAddress[owner] = claimDetails[claimDetails.length - 1].epochNumber; // <---------------
 //transfer reward
    owner.transfer(totalToClaim); // <-----------------------------
 emit Claim(signPublicKey, forgerVrf1, forgerVrf2, owner, claimDetails);
}
----end of code block ----
Remediation Plan
SOLVED:
The
Horizen Labs team
solved the issue by implementing the recommended solution.
Remediation Hash
https://github.com/HorizenLabs/eon-delegated-staking/pull/3/commits/b46a4025b1016635f8a90d31cb9a7abd39d7b710

Because of
if (block.number <= screeningStageEndBlock || block.number > endBlock) revert InvalidVote()
, the following
StandardFunding.fundingVote
function can only execute
uint128 newVotingPower = SafeCast.toUint128(_getVotesFunding(msg.sender, votingPower, voter.remainingVotingPower, screeningStageEndBlock))
when
block.number
is bigger than
screeningStageEndBlock
.
https://github.com/code-423n4/2023-05-ajna/blob/main/ajna-grants/src/grants/base/StandardFunding.sol#L519-L569
----new code block----
 function fundingVote(
        FundingVoteParams[] memory voteParams_
    ) external override returns (uint256 votesCast_) {
 uint24 currentDistributionId = _currentDistributionId;
​
        QuarterlyDistribution storage currentDistribution = _distributions[currentDistributionId];
        QuadraticVoter        storage voter               = _quadraticVoters[currentDistributionId][msg.sender];
​
 uint256 endBlock = currentDistribution.endBlock;
​
 uint256 screeningStageEndBlock = _getScreeningStageEndBlock(endBlock);
​
 // check that the funding stage is active
 if (block.number <= screeningStageEndBlock || block.number > endBlock) revert InvalidVote();
​
 uint128 votingPower = voter.votingPower;
​
 // if this is the first time a voter has attempted to vote this period,
 // set initial voting power and remaining voting power
 if (votingPower == 0) {
​
 // calculate the voting power available to the voting power in this funding stage
 uint128 newVotingPower = SafeCast.toUint128(_getVotesFunding(msg.sender, votingPower, voter.remainingVotingPower, screeningStageEndBlock));
​
            voter.votingPower          = newVotingPower;
            voter.remainingVotingPower = newVotingPower;
        }
​
        ...
    }
----end of code block ----
When the
StandardFunding.fundingVote
function calls the following
StandardFunding._getVotesFunding
function,
screeningStageEndBlock
would be used as the
voteStartBlock_
input for calling the
Funding._getVotesAtSnapshotBlocks
function below. Because
block.number
would always be bigger than
screeningStageEndBlock
,
voteStartBlock_
would always be
screeningStageEndBlock
in the
Funding._getVotesAtSnapshotBlocks
function. This means that the
Funding._getVotesAtSnapshotBlocks
function would always return the same voting power for the same voter at any
block.number
that is bigger than
screeningStageEndBlock
during the funding phase.
https://github.com/code-423n4/2023-05-ajna/blob/main/ajna-grants/src/grants/base/StandardFunding.sol#L891-L910
----new code block----
 function _getVotesFunding(
 address account_,
 uint256 votingPower_,
 uint256 remainingVotingPower_,
 uint256 screeningStageEndBlock_
    ) internal view returns (uint256 votes_) {
 // voter has already allocated some of their budget this period
 if (votingPower_ != 0) {
            votes_ = remainingVotingPower_;
        }
 // voter hasn't yet called _castVote in this period
 else {
            votes_ = Maths.wpow(
            _getVotesAtSnapshotBlocks(
                account_,
                screeningStageEndBlock_ - VOTING_POWER_SNAPSHOT_DELAY,
