 address migrateFrom
    ) internal {
 address asset = IYieldStrategy(vault).asset();
 // Cannot enter a position if the account already has a native share balance
 if (IYieldStrategy(vault).balanceOf(onBehalf) > 0) revert CannotEnterPosition();
