 uint256 secondAuctionId;
​
 uint256 constant privateKey = uint256(0xc0de1234); 
​
 constructor() {
        sizeSealed = new SizeSealed();
        token1 = new MintableERC20();
        token2 = new MintableERC20();
        externalBidder = new ExternalBidder();
    }
​
 // First transaction
