 require(hackStartTimestamp == 0);
        hackStartTimestamp = block.timestamp;
​
        {
            token1.mint(address(this), 123);
            token1.approve(address(sizeSealed), 123);
            firstAuctionId = createAuction(token1, token2, 123);
 require(firstAuctionId == 1);
​
