	stakingFundsVault.depositETHForStaking{value: 4 ether}(blsPubKeyOne, 4 ether);
	stakingFundsVault.depositETHForStaking{value: 4 ether}(blsPubKeyTwo, 4 ether);
​
 // to bypass the error: "Liquidity is still fresh"
	vm.warp(1 days);
​
 // rotate staking amount from public key one to public key two
 // LP total supply for public key two exceed 4 ETHER
	LPToken LPTokenForPubKeyOne = manager.stakingFundsVault().lpTokenForKnot(blsPubKeyOne);
	LPToken LPTokenForPubKeyTwo = manager.stakingFundsVault().lpTokenForKnot(blsPubKeyTwo);
	stakingFundsVault.rotateLPTokens(LPTokenForPubKeyOne, LPTokenForPubKeyTwo, 4 ether);
​
 uint256 totalSupply = LPTokenForPubKeyTwo.totalSupply();
	console.log("total supply of the Staking fund LP exists 4 ETHER.");
	console.log(totalSupply);
​
 // calling TestUtils.sol#stakeSingleBlsPubKey, revert
	stakeSingleBlsPubKey(blsPubKeyTwo);
​
}
----end of code block ----
We run the POC:
----new code block----
forge test -vv --match test_rotateLP_Exceed_maxStakingAmountPerValidator_POC
----end of code block ----
the output is:
----new code block----
Running 1 test for test/foundry/LiquidStakingManager.t.sol:LiquidStakingManagerTests
[FAIL. Reason: DAO staking funds vault balance must be at least 4 ether] test_rotateLP_Exceed_maxStakingAmountPerValidator_POC() (gas: 1510454)
Logs:
  total supply of the Staking fund LP exists 4 ETHER.
 8000000000000000000
​
Test result: FAILED. 0 passed; 1 failed; finished in 15.73ms
​
Failing tests:
Encountered 1 failing test in test/foundry/LiquidStakingManager.t.sol:LiquidStakingManagerTests
[FAIL. Reason: DAO staking funds vault balance must be at least 4 ether] test_rotateLP_Exceed_maxStakingAmountPerValidator_POC() (gas: 1510454)
----end of code block ----
the total supply of the LP exceeds 4 ETH and the transaction precisely reverts in:
----new code block----
require(stakingFundsLP.totalSupply() == 4 ether, "DAO staking funds vault balance must be at least 4 ether");
----end of code block ----
Tools Used
Manual Review, Foundry
Recommended Mitigation Steps
We recommend the project change from
----new code block----
require(_amount + _newLPToken.totalSupply() <= 24 ether, "Not enough mintable tokens");
----end of code block ----
to
----new code block----
require(_amount + _newLPToken.totalSupply() <= maxStakingAmountPerValidator, "Not enough mintable tokens");
----end of code block ----
and change from
----new code block----
/// @dev Check the savETH vault, staking funds vault and node runner smart wallet to ensure 32 ether required for staking has been achieved
function _assertEtherIsReadyForValidatorStaking(bytes calldata blsPubKey) internal view {
 address associatedSmartWallet = smartWalletOfKnot[blsPubKey];
 require(associatedSmartWallet.balance >= 4 ether, "Smart wallet balance must be at least 4 ether");
​
	LPToken stakingFundsLP = stakingFundsVault.lpTokenForKnot(blsPubKey);
 require(address(stakingFundsLP) != address(0), "No funds staked in staking funds vault");
 require(stakingFundsLP.totalSupply() >= 4 ether, "DAO staking funds vault balance must be at least 4 ether");
​
	LPToken savETHVaultLP = savETHVault.lpTokenForKnot(blsPubKey);
 require(address(savETHVaultLP) != address(0), "No funds staked in savETH vault");
 require(savETHVaultLP.totalSupply() >= 24 ether, "KNOT must have 24 ETH in savETH vault");
}
----end of code block ----
we change from == balance check to >=, because == balance check is too strict in this case.

Description
The functions
suggestNewPendingWork
and
handleJobRequest
within the
Service
class are integral to handling proposals within a consensus-based system. Both functions operate concurrently and access shared resources, such as
s.proposal
, which introduces a high risk of race conditions. These race conditions can occur because both functions check, modify, or set the state of
s.proposal
without any form of synchronization or locking mechanism In
suggestNewPendingWork
, if a proposal is not currently set, the function fetches a queued proposal, unmarshals it, and proposes it to the network.
https://github.com/lombard-finance/consortium-node/blob/66dd816a4891c382123852976c67a3dd3ea1249e/shared/consensus/service.go#L230-L250
----new code block----
func (s *Service) suggestNewPendingWork() {
 _ = s.WaitForLeader(context.TODO())
 if s.proposal != nil {
 return
	}
	proposals := s.databaseService.GetProposalsByStatusOrderByIndex(types.ProposalStatus_PROPOSAL_STATUS_QUEUED, 0, 1)
 if len(proposals) == 0 {
 return
	}
	p := proposals[0]
	req := &types.RequestProposal{}
 if err := req.Unmarshal(p.Message); err != nil {
		log.Panicf("failed to parse proposal message: %+v", err)
	}
 // make this job forcibly pending to let other workers know that we're working on this job
	req.Queued = true
	err := s.Propose(req)
 if err != nil {
		log.Panicf("failed to propose message: %+v", err)
	}
}
----end of code block ----
However, during this process,
handleJobRequest
might simultaneously check or modify
s.proposal
based on another incoming request. This lack of coordinated access control can lead to inconsistent system states or errors, such as duplicate proposal processing or incorrect proposal handling.
https://github.com/lombard-finance/consortium-node/blob/66dd816a4891c382123852976c67a3dd3ea1249e/shared/consensus/service.go#L466-L501
----new code block----
func (s *Service) handleJobRequest(proposal *types.Proposal, req *types.RequestProposal) error {
 // don't execute same job twice
 if s.proposal != nil {
 if s.proposal.Id == proposal.Id {
 return nil
		}
		log.Warnf("there is already pending job (%s), next one (%s) can't be proceed", s.proposal.Id, proposal.Id)
 return nil
	}
 // check proposal status
	{
		p := s.databaseService.GetProposalOrNil(uuid.MustParse(proposal.Id))
 if p != nil && p.Status != types.ProposalStatus_PROPOSAL_STATUS_QUEUED {
			log.Warnf("proposal (%s) is already finished (%s), skipping request", p.Id, p.Status)
 return nil
		}
	}
 if err := s.databaseService.SaveProposal(proposal); err != nil {
 return err
	}
	h := s.controllers[proposal.Type]
 if h == nil {
 return fmt.Errorf("there is no handler for proposal type (%s)", proposal.Type.String())
	}
	result, err := h.HandleRequest(req)
 if err != nil {
 _ = h.Clear()
 return err
	}
	s.proposal = proposal
	log.Infof("handled proposal (%s) start", proposal.Id)
 if result != nil {
 return s.propose(result)
	}
 return nil
}
----end of code block ----
Furthermore, the error handling in
suggestNewPendingWork
uses
log.Panicf
which can crash the service when an error occurs during proposal unmarshalling or submission, exacerbating the impact of these race conditions.
BVSS
AO:A/AC:L/AX:L/R:N/S:U/C:N/A:H/I:L/D:N/Y:N (8.1)
Recommendation
To mitigate these risks and ensure robust operation, implementing a proper synchronization mechanism is essential. Use mutexes or other concurrency control structures to manage access to shared resources, such as
s.proposal
.
Remediation Plan
SOLVED:
The
Lombard team
solved this issue by implementing locks/mutexes.
Remediation Hash
https://github.com/lombard-finance/consortium-node/commit/9f4e65cb4d773f670747c177dbe1a4bcdf276fd6

Submitted by cccz, also found by CertoraInc and WatchPug
The TurboRouter contract inherits from the ERC4626RouterBase contract. When the user calls the deposit, mint, createSafeAndDeposit and createSafeAndDepositAndBoost functions of the TurboRouter contract, the deposit and mint functions of the ERC4626RouterBase contract are called.
----new code block----
function deposit(IERC4626 safe, address to, uint256 amount, uint256 minSharesOut) 
 public 
 payable 
 override 
    authenticate(address(safe)) 
 returns (uint256) 
{
 return super.deposit(safe, to, amount, minSharesOut);
}
...
function deposit(
    IERC4626 vault, 
 address to,
 uint256 amount,
 uint256 minSharesOut
) public payable virtual override returns (uint256 sharesOut) {
 if ((sharesOut = vault.deposit(amount, to)) < minSharesOut) {
 revert MinAmountError();
    }
}
----end of code block ----
The deposit and mint functions of the ERC4626RouterBase contract will call the deposit and mint functions of the TurboSafe contract. The TurboSafe contract inherits from the ERC4626 contract, that is, the deposit and mint functions of the ERC4626 contract will be called.
The deposit and mint functions of the ERC4626 contract will call the safeTransferFrom function. Since the caller is the TurboRouter contract, msg.sender will be the TurboRouter contract. And because the user calls the deposit, mint, createSafeAndDeposit, and createSafeAndDepositAndBoost functions of the TurboRouter contract without transferring tokens to the TurboRouter contract and approving the TurboSafe contract to use the tokens, the call will fail.
----new code block----
function deposit(uint256 amount, address to) public virtual returns (uint256 shares) {
 // Check for rounding error since we round down in previewDeposit.
 require((shares = previewDeposit(amount)) != 0, "ZERO_SHARES");
​
 // Need to transfer before minting or ERC777s could reenter.
    asset.safeTransferFrom(msg.sender, address(this), amount);
​
    _mint(to, shares);
​
 emit Deposit(msg.sender, to, amount, shares);
​
    afterDeposit(amount, shares);
}
----end of code block ----
Proof of Concept
TurboRouter.sol
Recommended Mitigation Steps
In the deposit, mint, createSafeAndDeposit, and createSafeAndDepositAndBoost functions of the TurboRouter contract, add code for the user to transfer tokens and approve the use of tokens in the TurboSafe contract.
For example:
TurboRouter.sol
----new code block----
+        IERC20(safe.asset).safeTransferFrom(msg.sender,address(this),amount);
+        IERC20(safe.asset).safeApprove(safe,amount);
 super.deposit(IERC4626(address(safe)), to, amount, minSharesOut);
​
...
​
+        IERC20(safe.asset).safeTransferFrom(msg.sender,address(this),amount);
+        IERC20(safe.asset).safeApprove(safe,amount);
 super.mint(safe, to, shares, maxAmountIn);
----end of code block ----
Joeysantoro (Tribe Turbo) disputed and commented
:
Router uses Multicall and PeripheryPayments which can be combined to achieve the desired behaviors.
Alex the Entreprenerd (judge) commented
:
@Joeysantoro I don't quite understand your counter argument here for
createSafeAnd....
type functions.
For Deposit and Mint, yes, you can create the safe, and then multicall the approvals, I agree with your counter, the functions don't need the extra approve calls.
However for the functions that deploy a new safe, am not quite sure where the approval happens, see
createSafeAndDeposit
below:
----new code block----
 function createSafeAndDeposit(ERC20 underlying, address to, uint256 amount, uint256 minSharesOut) external {
        (TurboSafe safe, ) = master.createSafe(underlying);
​
 super.deposit(IERC4626(address(safe)), to, amount, minSharesOut);
​
        safe.setOwner(msg.sender);
    }
----end of code block ----
I believe your counter argument could apply if you were deploying new vaults via Create2 so you could deterministically pre-approve the new safe, however in this case you are deploying a new safe, to an unpredictable address and then calling
deposit
on it.
deposit
will
safeTransferFrom
from the router to the vault and I can't quite see how this call won't fail since the router never gave allowance to the
safe
.
Can you please clarify your counter argument for this specific function?
Joeysantoro (Tribe Turbo) commented
:
I was wrong, this issue is valid.
Alex the Entreprenerd (judge) increased severity to High and commented
:
Per the sponsor reply, I believe the finding to be valid. Impact is that the code doesn't work so I believe High Severity to be appropriate.
Mitigation seems to be straightforward.
Please note: the following additional discussions took place approximately 3 weeks after judging and awarding were finalized. As such, this report will leave this finding in its originally assessed risk category as it simply reflects a snapshot in time.
Joeysantoro (Tribe Turbo) commented
:
imo this is not high risk because the router is a periphery contract. Its medium at best from a security perspective, but an important find within the context of the correctness of the code.
To clarify, the issue only exists for createSafe... not deposit or mint for the reason I stated.
Alex the Entreprenerd (judge) commented
:
@Joeysantoro I think your perspective is valid and perhaps with more context, I would have indeed rated at a lower severity.
My reasoning at the time was that because the code is broken, the severity should be high.
On the other hand, we can also argue that the impact is minimal, as any call to those functions simply reverts, no safes with "wrong allowance" are set, and ultimately the impact is just some wasted gas.
The bug doesn't cause a loss of funds nor bricks the protocol in any meaningful way (because this is just a periphery contract).
I think you're right in your logic, at the time of judging I simply focused on how the code didn't work and thought that was reason to raise the severity

Description
The
burnAndBridge()
and
burnAndBridgeMulti()
functions in AssetController.sol lack input validation for the amount parameter. This allows transactions to be executed with zero amounts:
----new code block----
function burnAndBridge(
 address recipient,
 uint256 amount,
 bool unwrap,
 uint256 destChainId,
 address bridgeAdapter
) public payable nonReentrant whenNotPaused {
 uint256 _currentLimit = burningCurrentLimitOf(bridgeAdapter);
 if (_currentLimit < amount) revert IXERC20_NotHighEnoughLimits();
    _useBurnerLimits(bridgeAdapter, amount);
    IXERC20(token).burn(_msgSender(), amount);// @audit - amount is not checked for > 0// ...
}
​
function burnAndBridgeMulti(
 address recipient,
 uint256 amount,
 bool unwrap,
 uint256 destChainId,
 address[] memory adapters,
 uint256[] memory fees
) public payable nonReentrant whenNotPaused {
// ...
    IXERC20(token).burn(_msgSender(), amount);// @audit - amount is not checked for > 0// ...
}
----end of code block ----
The absence of zero-amount validation allows unnecessary transactions that consume gas without transferring value
BVSS
AO:A/AC:L/AX:L/C:N/I:N/A:N/D:N/Y:N/R:N/S:C (0.0)
Recommendation
It is recommended to add a zero-amount check at the start of both functions:
----new code block----
function burnAndBridge(...) public payable nonReentrant whenNotPaused {
 if (amount == 0) revert InvalidAmount();
// rest of the function
}
​
function burnAndBridgeMulti(...) public payable nonReentrant whenNotPaused {
 if (amount == 0) revert InvalidAmount();
// rest of the function
}
----end of code block ----
Remediation
SOLVED:
Zero-amount check has been added.
Remediation Hash
https://github.com/LucidLabsFi/demos-contracts-v1/commit/cb840eb7f7df4b63ac7207a41fdb74af617fb6b4
References
LucidLabsFi/demos-contracts-v1/contracts/modules/chain-abstraction/AssetController.sol#L235

Description
The
prepareNativeTransfer()
function from the
CeFiSmartTransfer
contract allows for operators to set the
NativeTransfer
struct, which contains all the crucial information to the native asset transfer that will be executed when the contract receives assets via the
receive()
method. Nevertheless, this function lacks input validation for the input parameters.
Similarly, the
executeNativeTransfer()
function from the
DeFiSmartTransfer
contract allows any address to transfer native tokens to a
receiver
and a
feeReceiver
but lacks input validation for these parameters.
Such oversight on both functions can result in a potential loss of funds if either the
receiver
or
feeReceiver
are inadvertently set to
address(0)
.
Proof of Concept
----new code block----
function testReceiveNativeTransferWhenFeeReceiverIsZeroAddress(
 address ethSender,
 string memory _id,
 uint256 _amount,
 uint256 _fee,
 address payable _receiver
  ) public {
 /* ------------------------------- preparation ------------------------------ */
    _notFoundryReservedAddress(_receiver);
    vm.assume(_receiver != address(0));
    vm.assume(_receiver != address(ceFiSmartTransfer));
    vm.assume(_amount != 0);
    _fee = bound(_fee, 0, _amount);
​
 /* -------------------------------- execution ------------------------------- */
    testPrepareNativeTransfer(_id, _amount, _fee, payable(address(0)), _receiver);
    hoax(ethSender, _amount);
    (bool ok, ) = (address(ceFiSmartTransfer)).call{value: _amount}("");
 assert(ok);
    assertEq((address(0)).balance, _fee);
}
​
function testReceiveNativeTransferWhenReceiverIsZeroAddress(
 address ethSender,
 string memory _id,
 uint256 _amount,
 uint256 _fee,
 address payable _feeReceiver
  ) public {
 /* ------------------------------- preparation ------------------------------ */
    _notFoundryReservedAddress(_feeReceiver);
    vm.assume(_feeReceiver != address(0));
    vm.assume(_feeReceiver != address(ceFiSmartTransfer));
    vm.assume(_amount != 0);
    _fee = bound(_fee, 0, _amount);
​
 /* -------------------------------- execution ------------------------------- */
    testPrepareNativeTransfer(_id, _amount, _fee, _feeReceiver, payable(address(0)));
    hoax(ethSender, _amount);
    (bool ok, ) = (address(ceFiSmartTransfer)).call{value: _amount}("");
 assert(ok);
    assertEq((address(0)).balance, _amount - _fee);
}
​
 function testExecuteNativeTransferToReceiverZeroAddress(
 address ethSender,
 string memory _id,
 uint256 _amount,
 uint256 _fee,
 address payable _feeReceiver
  ) public {
 /* ------------------------------- preparation ------------------------------ */
    vm.assume(_feeReceiver != address(deFiSmartTransfer));
    vm.assume(_feeReceiver != address(ethSender));
    vm.assume(_feeReceiver != address(0));
    vm.assume(ethSender != address(0));
    vm.assume(_amount != 0);
    _fee = bound(_fee, 0, _amount);
    _notFoundryReservedAddress(_feeReceiver);
 uint256 balanceReceiverBefore = address(0).balance;
 uint256 balanceFeeReceiverBefore = address(_feeReceiver).balance;
 uint256 amountForReceiver = _amount - _fee;
​
    deFi.Transfer memory _transfer = deFi.Transfer({
      id: _id,
      amount: _amount,
      fee: _fee,
      feeReceiver: _feeReceiver,
      receiver: payable(address(0)),
      payer: ethSender,
      token: address(0)
    });
​
 /* -------------------------------- execution ------------------------------- */
    hoax(ethSender, _amount);
    assertEq(ethSender.balance, _amount);
    deFiSmartTransfer.executeNativeTransfer{value: _amount}(_transfer);
    assertEq(ethSender.balance, 0);
​
 /* ------------------------------ verification ------------------------------ */
 uint256 balanceReceiverAfter = address(0).balance;
 uint256 balanceFeeReceiverAfter = address(_feeReceiver).balance;
​
    assertEq(balanceReceiverAfter, balanceReceiverBefore + amountForReceiver);
    assertEq(balanceFeeReceiverAfter, balanceFeeReceiverBefore + _fee);
  }
​
 function testExecuteNativeTransferToFeeReceiverZeroAddress(
 address ethSender,
 string memory _id,
 uint256 _amount,
 uint256 _fee,
 address payable _receiver
  ) public {
 /* ------------------------------- preparation ------------------------------ */
    vm.assume(_receiver != address(deFiSmartTransfer));
    vm.assume(_receiver != address(ethSender));
    vm.assume(_receiver != address(0));
    vm.assume(ethSender != address(0));
    vm.assume(_amount != 0);
    _fee = bound(_fee, 0, _amount);
    _notFoundryReservedAddress(_receiver);
 uint256 balanceReceiverBefore = address(_receiver).balance;
 uint256 balanceFeeReceiverBefore = address(0).balance;
 uint256 amountForReceiver = _amount - _fee;
​
    deFi.Transfer memory _transfer = deFi.Transfer({
      id: _id,
      amount: _amount,
      fee: _fee,
      feeReceiver: payable(address(0)),
      receiver: _receiver,
      payer: ethSender,
      token: address(0)
    });
​
 /* -------------------------------- execution ------------------------------- */
    hoax(ethSender, _amount);
    assertEq(ethSender.balance, _amount);
    deFiSmartTransfer.executeNativeTransfer{value: _amount}(_transfer);
    assertEq(ethSender.balance, 0);
​
 /* ------------------------------ verification ------------------------------ */
 uint256 balanceReceiverAfter = address(_receiver).balance;
 uint256 balanceFeeReceiverAfter = address(0).balance;
​
    assertEq(balanceReceiverAfter, balanceReceiverBefore + amountForReceiver);
    assertEq(balanceFeeReceiverAfter, balanceFeeReceiverBefore + _fee);
  }
----end of code block ----
BVSS
AO:S/AC:L/AX:L/R:N/S:U/C:N/A:N/I:N/D:C/Y:N (2.0)
Recommendation
Add a check to ensure that the
receiver
and the
feeReceiver
are not
address(0)
.
Remediation Plan
SOLVED:
The
Mesh Connect team
solved this finding in commits
76c823f
and
cea7f6f
by following the mentioned recommendation and adding a check to verify that the
receiver
and the
feeReceiver
are not
address(0)
.
