DeFiSmartTransfer.sol#L26-L43

Severity: Medium Risk
Context
File:
RedstoneCoreOracle.sol
Lines:
L70-L93
Description
The current logic of the RedstoneCoreOracle implementation uses
block.timestamp
as the timestamp to which a price has been observed instead of the real observation timestamp that is bound to the price itself. The
validateTimestamp
function allows the user to pick up a price that is at most
maxPriceStaleness
seconds in the past and one minute in the future.
The comparison is made between the oracle price observed timestamp and
block.timestamp
but does not verify that the price's timestamp is older than the current one stored in the contract inside the
cacheUpdatedAt
and
cachedPrice
. Given the checks made in
updatePrice
,
validateTimestamp
, and
_getQuote
, it's possible for an attacker to pick up a price in several data packages that will be considered valid and will be older than the current selected one. This could allow an attacker to select a price that benefits operations performed on vaults where such price will be used, potentially leading to borrowing more than expected or liquidating a user that should not be liquidated.
Current Configuration:
maxCacheStaleness = 60
(1 minute)
maxPriceStaleness = 180
(3 minutes, the one used by default by Redstone in their SDK, see
RedstoneDefaultsLib
)
Starting Data:
cachedPrice = 0
cacheUpdatedAt = 0
block.timestamp = 1000
Flow:
T0:
updatePrice()
is called with a
price.timestamp
(signed price timestamp) 60 seconds in the future compared to
block.timestamp
.
price.timestamp = 1060
updatePrice
check:
! block.timestamp <= maxCacheStaleness + cacheUpdatedAt
⇒
1000 <= 60 + 0
⇒
!FALSE
⇒ do not revert, OK.
validateTimestamp
check:
! timestamp - block.timestamp > TIMESTAMP_AHEAD_SECONDS
⇒
1060 - 1000 > 180
⇒
!FALSE
⇒ do not revert, OK.
All checks passed meaning that:
cacheUpdatedAt
is updated to
1000
cachedPrice
is updated to
X
(
price1.value
)
T0+:
Any call to
updatePrice()
done before
cacheUpdatedAt + maxCacheStaleness + 1
will skip the price update.
T1:
block.timestamp = 1061
, call
updatePrice
with
newPrice.timestamp = 1059
updatePrice
check:
! block.timestamp <= maxCacheStaleness + cacheUpdatedAt
⇒
1061 <= 60 + 1000
⇒
!FALSE
⇒ do not revert, OK.
validateTimestamp
check:
staleness = block.timestamp - timestamp = 1061 - 1059 = 2
staleness > maxPriceStaleness = 2 > 180
⇒
FALSE
⇒ do not revert, OK.
cacheUpdatedAt
is updated at
1061
.
cachedPrice
is updated to
X
(
price2.value
).
The result is that
price2
was older than
price1
, but the
RedstoneCoreOracle
has allowed the caller to submit and store such a price (
price1.timestamp = 1060
,
price2.timestamp = 1059
).
Test
The following test replicates the behavior of the
RedstoneCoreOracle
, modifying the logic of the contract for the sake of simplicity:
----new code block----
// SPDX-License-Identifier: GPL-2.0-or-later
pragma solidity 0.8.23;
​
import {Test, console} from "forge-std/Test.sol";
import {Errors} from "src/lib/Errors.sol";
​
contract RSNewPriceInThePastTest is Test {
 uint256 DEFAULT_MAX_DATA_TIMESTAMP_AHEAD_SECONDS;
 uint256 maxPriceStaleness;
 uint256 maxCacheStaleness;
 uint208 cachedPrice;
 uint48 cacheUpdatedAt;
 uint256 cachedId;
​
 struct RedstonePrice {
 uint256 id;
 uint48 timestamp;
 uint208 price;
    }
​
 function setUp() public {
        DEFAULT_MAX_DATA_TIMESTAMP_AHEAD_SECONDS = 60; // the same as the one from Redstone
    }
​
 function testPriceInThePast() external {
        maxCacheStaleness = 60;
        maxPriceStaleness = 180;
​
 // set the block.timestamp to 1000
        vm.warp(1000);
        assertEq(block.timestamp, 1000);
​
 // FIRST PRICE: in the future of 60 seconds
 uint48 price1Timestamp = 1060;
        RedstonePrice memory priceInTheFuture = RedstonePrice({id: 1, timestamp: price1Timestamp * 1000, price: 1000});
        updatePrice(priceInTheFuture);
        assertEq(cachedId, priceInTheFuture.id);
        assertEq(cachedPrice, priceInTheFuture.price);
        assertEq(cacheUpdatedAt, 1000); // current block.timestamp
​
 // just assert that it does not revert
        _getQuote(1, address(0), address(0));
​
 // SECOND PRICE: 1 second BEFORE the current price signed timestamp
 uint48 price2Timestamp = price1Timestamp - 1;
        RedstonePrice memory priceInThePast = RedstonePrice({id: 2, timestamp: price2Timestamp * 1000, price: 500});
​
 // if we try to update before that maxCacheStaleness has passed, it will just return and skip
        vm.warp(1000 + maxCacheStaleness); // still need 1 second
        assertEq(block.timestamp, 1000 + maxCacheStaleness);
​
 // just assert that it does not revert
        updatePrice(priceInThePast);
​
 // assert that nothing has changed
        assertEq(cachedId, priceInTheFuture.id);
​
 // warp 1 second more compared to before, now we should be able to
        vm.warp(1000 + maxCacheStaleness + 1);
        assertEq(block.timestamp, 1000 + maxCacheStaleness + 1);
​
 // now we can update the price
        updatePrice(priceInThePast);
        assertEq(cachedId, priceInThePast.id);
        assertEq(cachedPrice, priceInThePast.price);
        assertEq(cacheUpdatedAt, 1000 + maxCacheStaleness + 1); // current block.timestamp
​
 // just assert that it does not revert
        _getQuote(1, address(0), address(0));
    }
​
 function updatePrice(RedstonePrice memory proposedPrice) internal {
 // Use the cache if it has not expired.
 if (block.timestamp <= maxCacheStaleness + cacheUpdatedAt) return;
​
        proposedPrice = getOracleNumericValueFromTxMsg(proposedPrice);
 if (proposedPrice.price > type(uint208).max) revert Errors.PriceOracle_Overflow();
​
 // update values
        cachedId = uint48(proposedPrice.id);
        cachedPrice = uint208(proposedPrice.price);
        cacheUpdatedAt = uint48(block.timestamp);
    }
​
 function getOracleNumericValueFromTxMsg(RedstonePrice memory proposedPrice) internal returns (RedstonePrice memory) {
 // redstone validation here
 // callback to validate the price timestamp
        validateTimestamp(proposedPrice);
 // validation performed, return the validated price
 return proposedPrice;
    }
​
 function validateTimestamp(RedstonePrice memory proposedPrice) internal {
 uint256 timestamp = proposedPrice.timestamp / 1000;
 if (block.timestamp > timestamp) {
 uint256 staleness = block.timestamp - timestamp;
            console.log("block.timestamp", block.timestamp);
            console.log("timestamp", timestamp);
            console.log("staleness", staleness);
            console.log("maxPriceStaleness", maxPriceStaleness);
 if (staleness > maxPriceStaleness) revert Errors.PriceOracle_TooStale(staleness, maxPriceStaleness);
        } else if (timestamp - block.timestamp > DEFAULT_MAX_DATA_TIMESTAMP_AHEAD_SECONDS) {
 revert Errors.PriceOracle_InvalidAnswer();
        }
    }
​
 function _getQuote(uint256 inAmount, address _base, address _quote) internal view returns (uint256) {
 uint256 staleness = block.timestamp - cacheUpdatedAt;
 if (staleness > maxCacheStaleness) revert Errors.PriceOracle_TooStale(staleness, maxCacheStaleness);
 // we don’t care, it just must not revert
 return 1;
    }
}
----end of code block ----
Recommendation
Given that Redstone oracle offers "observation timestamp" for their prices, Euler should take advantage of this feature and store such timestamp in the
cacheUpdatedAt
state variable instead of
block.timestamp
. Any price that is before the observation timestamp of the current cached price should be considered invalid.
Unfortunately, it appears that the Redstone SDK does not offer an easy way to override the needed functions or inject callbacks/hooks to pick the observation timestamp of the selected price returned by
getOracleNumericValueFromTxMsg
.
Euler should:
Document this behavior and select
maxCacheStaleness
and
maxPriceStaleness
to minimize this scenario.
Rebuild the Redstone SDK in a way that allows them to extract the
extractedTimestamp
of the selected price returned by
getOracleNumericValueFromTxMsg
.
Euler:
The issue has been mitigated by rewriting the RedStone Oracle to a more lightweight version in commit
5c5cbf8d
.
Spearbit:
Resolved.

Description
The
GeniusGasTank
contract's
sponsorOrderedTransactions
function increments the user's nonce only at the end of the function during event emission, after performing external contract interactions. This implementation violates the
Checks-Effects-Interactions
pattern:
----new code block----
function sponsorOrderedTransactions(
 address target,
 bytes calldata data,
    IAllowanceTransfer.PermitBatch calldata permitBatch,
 bytes calldata permitSignature,
 address owner,
 address feeToken,
 uint256 feeAmount,
 uint256 deadline,
 bytes calldata signature
) external payable override whenNotPaused {
 if (deadline < block.timestamp) revert GeniusErrors.DeadlinePassed(deadline);
​
 bytes32 messageHash = keccak256(abi.encode(target,data,permitBatch,nonces[owner],feeToken,feeAmount,deadline,address(this)));
​
    _verifySignature(messageHash, signature, owner);
 address[] memory tokensIn = _permitAndBatchTransfer(
        permitBatch,
        permitSignature,
        owner,
        feeToken,
        feeAmount
    );
    IERC20(feeToken).safeTransfer(feeRecipient, feeAmount);
​
 if (target == address(PROXYCALL)) PROXYCALL.execute{value: msg.value}(target, data);
 else {
        PROXYCALL.approveTokensAndExecute{value: msg.value}(
            tokensIn,
            target,
            data
        );
    }
​
 emit OrderedTransactionsSponsored(msg.sender,owner,target,feeToken,feeAmount,nonces[owner]++);
}
​
​
----end of code block ----
The nonce increment occurs after multiple external interactions, including token transfers and proxy calls.
Impact:
State changes occur after external contract calls
The execution order breaks smart contract security best practices
Creates an unnecessary reentrancy vector despite the overall safety of the implementation
BVSS
AO:A/AC:L/AX:L/C:N/I:N/A:L/D:N/Y:N/R:N/S:U (2.5)
Recommendation
It is recommended to move the nonce increment before any external interactions:
----new code block----
function sponsorOrderedTransactions(
 // ... parameters ...
) external payable override whenNotPaused {
 if (deadline < block.timestamp) revert GeniusErrors.DeadlinePassed(deadline);
​
 bytes32 messageHash = keccak256(abi.encode(target,data,permitBatch,nonces[owner],feeToken,feeAmount,deadline,address(this)));
    _verifySignature(messageHash, signature, owner);
​
 uint256 currentNonce = nonces[owner];
    nonces[owner] = currentNonce + 1;// Increment nonce early
​
 address[] memory tokensIn = _permitAndBatchTransfer(
        permitBatch,
        permitSignature,
        owner,
        feeToken,
        feeAmount
    );
​
 // ... rest of the function ...
​
 emit OrderedTransactionsSponsored(msg.sender,owner,target,feeToken,feeAmount,currentNonce);
}
----end of code block ----
Remediation
SOLVED:
Nonce is now incremented after the verification of the signature.
Remediation Hash
https://github.com/Shuttle-Labs/genius-contracts/commit/6aa3e85d2d663413b100db32668ac1d1a2194926
References
Shuttle-Labs/genius-contracts/src/GeniusGasTank.sol#L64

Resolution
Partially fixed in commit
08248a9273fdbc22c1f59178d2124656dc8569ac
.
Although the
lock
modifier has been added to the
setFee
function, it remains possible to call
advancePeriod
before the pool is initialized. The Ramses team acknowledges this and has chosen to retain the option of not initializing pools upon deployment to accommodate specific use cases.
Description
In the
RamsesV3Pool
contract there is a
lock
modifier, which works not only as reentrancy protection, but also prevents entrance to a function before the pool is initialized. Some of the functions are missing this
lock
modifier without any reason to do that, allowing to call this function while the pool is not initialized. For example the
setFee
function of
RamsesV3Pool
doesn’t have
lock
modifier, while a very similar function also related to the fees -
setFeeProtocol
- has this modifier.
If the deployer has configured the
sqrtPriceX96
value to be zero, the pool wouldn’t be initialized, but a part of its functions will be available and anyone can change storage values of an unitialized pool, for example:
By calling
_advancePeriod
it’s possible to create an initial observation in the pool, while later calling
initialize
function will rewrite this observation back to zero, however it won’t rewrite the
_lastPeriod
variable, leading to inconsistency in the system.
By calling
slot0
view function, the function will return
_slot0.sqrtPriceX96
,
_slot0.tick
,
_slot0.observationCardinality
,
_slot0.observationCardinalityNext
as zeroes, while for example the
MIN_SQRT_RATIO
is
4295128739
, so the zero
sqrtPriceX96
is completely incorrect for the system.
and other view function will return values for the incorrect pool state.
Consider the following PoC:
----new code block----
        it.only("not initialized pool example", async () => {
 // make sure the pool is not initialized
            await expect(
                mint(wallet.address, 0n, -tickSpacing, tickSpacing, 1n),
            ).to.be.revertedWithCustomError(pool, "LOK");
​
 // calling _advancePeriod for the uninitialized pool works
            await pool._advancePeriod();

 // initialize the pool at price of 10:1, it rewrites the observation
            await pool.initialize(encodePriceSqrt(1n, 10n).toString());
​
        });
​
----end of code block ----
Examples
contracts/CL/core/RamsesV3Pool.sol:L758-L787
----new code block----
function _advancePeriod() public {
    PoolStorage.PoolState storage $ = PoolStorage.getStorage();
​
 // if in new week, record lastTick for previous period
 // also record secondsPerLiquidityCumulativeX128 for the start of the new period
 uint256 _lastPeriod = $.lastPeriod;
 if ((_blockTimestamp() / 1 weeks) != _lastPeriod) {
        Slot0 memory _slot0 = $.slot0;
 uint256 period = _blockTimestamp() / 1 weeks;
        $.lastPeriod = period;
​
 // start new period in obervations
 uint160 secondsPerLiquidityCumulativeX128 = Oracle.newPeriod(
            $.observations,
            _slot0.observationIndex,
            period
        );
​
 // record last tick and secondsPerLiquidityCumulativeX128 for old period
        $.periods[_lastPeriod].lastTick = _slot0.tick;
        $.periods[_lastPeriod].endSecondsPerLiquidityPeriodX128 = secondsPerLiquidityCumulativeX128;
​
 // record start tick and secondsPerLiquidityCumulativeX128 for new period
        PeriodInfo memory _newPeriod;
​
        _newPeriod.previousPeriod = uint32(_lastPeriod);
        _newPeriod.startTick = _slot0.tick;
        $.periods[period] = _newPeriod;
    }
}
​
----end of code block ----
contracts/CL/core/RamsesV3Pool.sol:L45-L54
----new code block----
/// @dev Mutually exclusive reentrancy protection into the pool to/from a method. This method also prevents entrance
/// to a function before the pool is initialized. The reentrancy guard is required throughout the contract because
/// we use balance checks to determine the payment status of interactions such as mint, swap and flash.
modifier lock() {
    PoolStorage.PoolState storage $ = PoolStorage.getStorage();
 if (!$.slot0.unlocked) revert LOK();
    $.slot0.unlocked = false;
 _;
    $.slot0.unlocked = true;
}
​
----end of code block ----
contracts/CL/core/RamsesV3Factory.sol:L56-L87
----new code block----
function createPool(
 address tokenA,
 address tokenB,
 int24 tickSpacing,
 uint160 sqrtPriceX96
) external override returns (address pool) {
 require(tokenA != tokenB, IT());
    (address token0, address token1) = tokenA < tokenB ? (tokenA, tokenB) : (tokenB, tokenA);
 require(token0 != address(0), A0());
 uint24 fee = tickSpacingInitialFee[tickSpacing];
 require(fee != 0, F0());
 require(getPool[token0][token1][tickSpacing] == address(0), PE());
​
    parameters = Parameters({
        factory: address(this),
        token0: token0,
        token1: token1,
        fee: fee,
        tickSpacing: tickSpacing
    });
    pool = IRamsesV3PoolDeployer(RamsesV3PoolDeployer).deploy(token0, token1, tickSpacing);
 delete parameters;
​
    getPool[token0][token1][tickSpacing] = pool;
 // populate mapping in the reverse direction, deliberate choice to avoid the cost of comparing addresses
    getPool[token1][token0][tickSpacing] = pool;
 emit PoolCreated(token0, token1, fee, tickSpacing, pool);
​
 if (sqrtPriceX96 > 0) {
        IRamsesV3Pool(pool).initialize(sqrtPriceX96);
    }
}
​
----end of code block ----
