 if (params.depositWhitelist && params.depositorWhitelistRoleHolder == address(0)) {
 revert Vault__MissingRoles();
    }
​
 if (!params.depositWhitelist && params.depositorWhitelistRoleHolder != address(0)) {
 revert Vault__InconsistentRoles();
    }
 // [...code...]
