 if (!entered && address(user) == to && IERC20(address(bunniToken)).balanceOf(address(user)) == 0) {
            entered = true;
            console2.log("making re-entrant deposit");
​
 uint256 depositAmount0 = 1 ether;
 uint256 depositAmount1 = 1 ether;
