 // Both inequalities hold true for all possible values of `_minGas`.
            gasSent := gas() // @audit this operation costs 2 gas
            _success := call(
                gas(), // gas
                _target, // recipient
                _value, // ether value
                add(_calldata, 32), // inloc
                mload(_calldata), // inlen
 0x00, // outloc
 0x00 // outlen
            )
        }
        console.log("gasSent =", gasSent);
 return _success;
    }
}
​
