        vm.startPrank(owner);
         // Define local variables for the parameters

        ...snip
​
        //does not revert
        updateRule.CalculateNewWeights(
        prevWeights,
        data,
        address(mockPool),
        parameters,
        lambdas,
        uint64(uint256(epsilonMax)),
        uint64(0.2e18));
​
        // @audit - the same parameters are ok
+       //does revert
+       updateRule.CalculateNewWeights(
+       prevWeights,
+       data,
