​
 function _beforeTokenTransfer(address , address , uint256 ) internal override {
 if(timesEntered == 0){
 try vault.changeAdapter() { // -------- STRUCTURE USED FOR SIMPLICITY
         timesEntered++;
       } catch {}
     }
   }
