Note: For test to run successfully, I added the following to veRAACToken::BoostStateView :
----new code block----
 /**
 * @notice View struct for boost state information
 */
 struct BoostStateView {
 uint256 minBoost; // Minimum boost multiplier in basis points
 uint256 maxBoost; // Maximum boost multiplier in basis points
 uint256 boostWindow; // Time window for boost calculations
 uint256 totalVotingPower; // Total voting power in the system
 uint256 totalWeight; // Total weight of all locks
        TimeWeightedAverage.Period boostPeriod; // Global boost period //c for testing purposes
    }
​
 function getBoostState() external view returns (BoostStateView memory) {
 return
            BoostStateView({
                minBoost: _boostState.minBoost,
                maxBoost: _boostState.maxBoost,
                boostWindow: _boostState.boostWindow,
                totalVotingPower: _boostState.totalVotingPower,
                totalWeight: _boostState.totalWeight,
                boostPeriod: _boostState.boostPeriod //c for testing purposes
            });
    }
----end of code block ----
This was a view function and I adapted it to allow for viewing the period's data.
Impact
This vulnerability poses a critical governance risk, as it can prevent users from locking RAACTokens and obtaining veRAAC voting power during key decision-making periods. If a governance vote is scheduled while this bug is active, affected users will be unable to participate, leading to skewed governance outcomes. Malicious actors could strategically trigger this issue to block new veRAAC holders from voting, ensuring only pre-existing stakeholders influence decisions. This creates centralization risks, as governance control shifts to a small group of participants. Additionally, users unable to lock tokens may miss out on governance incentives.
Tools Used
Manual Review, Hardhat
Recommendations
Update Period Validation in createPeriod
Modify the if condition in TimeWeightedAverage::createPeriod to use boostWindow rather than totalDuration:
----new code block----
if (
self.startTime != 0 &&
startTime < self.startTime + boostWindow //  Use boostWindow instead of totalDuration
) {
revert PeriodNotElapsed();
}
​
----end of code block ----
This ensures that period validation remains consistent and does not revert incorrectly.

Severity: Medium Risk
Context
Files:
Receiver.sol#L254
,
Receiver.sol#L282
Description
The Receiver contract is designed to gracefully return the funds to users. It reserves the gas for recovering gas before doing swaps via
executor.swapAndCompleteBridgeTokens
. The logic of reserving gas for recovering funds is implemented at
Receiver.sol#L236-L258
.
----new code block----
contract Receiver is ILiFi, ReentrancyGuard, TransferrableOwnership {
 // ...
 if (reserveRecoverGas && gasleft() < _recoverGas) {
 // case 1a: not enough gas left to execute calls
        receiver.call{ value: amount }("");
 // ...
    }
 // case 1b: enough gas left to execute calls
 try
        executor.swapAndCompleteBridgeTokens{
 value: amount,
 gas: gasleft() - _recoverGas
        }(_transactionId, _swapData, assetId, receiver) 
    {} catch {
        receiver.call{ value: amount }("");
    }
 // ...
}
----end of code block ----
The
gasleft()
function returns the remaining gas of a call. It is continuously decreasing. The second query of
gasleft()
is smaller than the first query. Hence, if the attacker tries to relay the transaction with a carefully crafted gas where
gasleft() >= _recoverGas
at the first query and
gasleft() - _recoverGas
reverts, this results in the token loss in the Receiver contract.
Recommendation
Recommend to cache the
gasleft()
:
----new code block----
if (LibAsset.isNativeAsset(assetId)) {
 // case 1: native asset
 + uint256 cacheGasleft = gasleft();
 - if (reserveRecoverGas && gasleft() < _recoverGas) {
 + if (reserveRecoverGas && cacheGasleft < _recoverGas) {
 // case 1a: not enough gas left to execute calls
        receiver.call{ value: amount }("");
 emit LiFiTransferRecovered(
            _transactionId,
            assetId,
            receiver,
            amount,
 block.timestamp
        );
 return;
    }
 // case 1b: enough gas left to execute calls
 try
        executor.swapAndCompleteBridgeTokens{
 value: amount,
 - gas: gasleft() - _recoverGas
 + gas: cacheGasleft - _recoverGas
        }(_transactionId, _swapData, assetId, receiver) 
    {} catch {
        receiver.call{ value: amount }("");
    }
} else {
    LiFi: Solved in PR 249.
    Spearbit: Verified.
----end of code block ----

Source: https://github.com/sherlock-audit/2024-12-seda-protocol-judging/issues/30
Found by
Boy2000, stuart_the_minion
Summary
Late/slow precommit votes, after +2/3 votes do not trigger VerifyVoteExtensionHandler.
ProcessProposalHandler
expects all vote extensions to be valid. Single malicious/misbehaving validator can inject invalid vote extension to the (previous) block, resulting in chain halt.
Root Cause
PrepareProposal does not re-verify/ignore invalid LocalLastCommit votes
https://github.com/sherlock-audit/2024-12-seda-protocol/blob/main/seda-chain/app/abci/handlers.go#L177
----new code block----
func (h *Handlers) PrepareProposalHandler() sdk.PrepareProposalHandler {
 return func(ctx sdk.Context, req *abcitypes.RequestPrepareProposal) (*abcitypes.ResponsePrepareProposal, error) {
 // Check if there is a batch whose signatures must be collected
 // at this block height.
 var collectSigs bool
		_, err := h.batchingKeeper.GetBatchForHeight(ctx, ctx.BlockHeight()+BlockOffsetCollectPhase)
 if err != nil {
 if !errors.Is(err, collections.ErrNotFound) {
 return nil, err
			}
		} else {
			collectSigs = true
		}
​
 var injection []byte
 if req.Height > ctx.ConsensusParams().Abci.VoteExtensionsEnableHeight && collectSigs {
			err := baseapp.ValidateVoteExtensions(ctx, h.stakingKeeper, req.Height, ctx.ChainID(), req.LocalLastCommit)
 if err != nil {
 return nil, err
			}
​
@>			injection, err = json.Marshal(req.LocalLastCommit)
 if err != nil {
				h.logger.Error("failed to marshal extended votes", "err", err)
 return nil, err
			}
​
			injectionSize := int64(len(injection))
 if injectionSize > req.MaxTxBytes {
				h.logger.Error(
 "vote extension size exceeds block size limit",
 "injection_size", injectionSize,
 "MaxTxBytes", req.MaxTxBytes,
				)
 return nil, ErrVoteExtensionInjectionTooBig
			}
			req.MaxTxBytes -= injectionSize
		}
​
		defaultRes, err := h.defaultPrepareProposal(ctx, req)
 if err != nil {
			h.logger.Error("failed to run default prepare proposal handler", "err", err)
 return nil, err
		}
​
		proposalTxs := defaultRes.Txs
 if injection != nil {
			proposalTxs = append([][]byte{injection}, proposalTxs...)
			h.logger.Debug("injected local last commit", "height", req.Height)
		}
 return &abcitypes.ResponsePrepareProposal{
			Txs: proposalTxs,
		}, nil
	}
}
----end of code block ----
ProcessProposalHandler expects all votes (batches) to be valid/verified
https://github.com/sherlock-audit/2024-12-seda-protocol/blob/main/seda-chain/app/abci/handlers.go#L235
----new code block----
func (h *Handlers) ProcessProposalHandler() sdk.ProcessProposalHandler {
 return func(ctx sdk.Context, req *abcitypes.RequestProcessProposal) (*abcitypes.ResponseProcessProposal, error) {
 if req.Height <= ctx.ConsensusParams().Abci.VoteExtensionsEnableHeight {
 return h.defaultProcessProposal(ctx, req)
		}
​
		batch, err := h.batchingKeeper.GetBatchForHeight(ctx, ctx.BlockHeight()+BlockOffsetCollectPhase)
 if err != nil {
 if errors.Is(err, collections.ErrNotFound) {
 return h.defaultProcessProposal(ctx, req)
			}
 return nil, err
		}
​
 var extendedVotes abcitypes.ExtendedCommitInfo
 if err := json.Unmarshal(req.Txs[0], &extendedVotes); err != nil {
			h.logger.Error("failed to decode injected extended votes tx", "err", err)
 return nil, err
		}
​
 // Validate vote extensions and batch signatures.
		err = baseapp.ValidateVoteExtensions(ctx, h.stakingKeeper, req.Height, ctx.ChainID(), extendedVotes)
 if err != nil {
 return nil, err
		}
​
 for _, vote := range extendedVotes.Votes {
 // Only consider extensions with pre-commit votes.
 if vote.BlockIdFlag == cmttypes.BlockIDFlagCommit {
				err = h.verifyBatchSignatures(ctx, batch.BatchNumber, batch.BatchId, vote.VoteExtension, vote.Validator.Address)
 if err != nil {
@>					h.logger.Error("proposal contains an invalid vote extension", "vote", vote)
 return nil, err
				}
			}
		}
​
		req.Txs = req.Txs[1:]
 return h.defaultProcessProposal(ctx, req)
	}
}
