​
 function _setShares(address _wallet, uint256 _amount, bool _sharesRemoving) internal {
>>>     _processFeesIfApplicable();
 if (_sharesRemoving) {
            _removeShares(_wallet, _amount);
 emit RemoveShares(_wallet, _amount);
