// SaturatingSub subtracts two integers without overflow
func SaturatingSub[T Signed](a, b T) T {
    diff := a - b
 if b < 0 && diff < a {
 return MaxSignedValue[T]()
    }
 if b > 0 && diff > a {
 return MinSignedValue[T]()
    }
 return diff
