 if b > 0 && a > math.MaxInt64-b {
            expected = math.MaxInt64
        } else if b < 0 && a < math.MinInt64-b {
            expected = math.MinInt64
        }
 if sum != expected {
            t.Errorf("SaturatingAdd(%v, %v) = %v; want %v", a, b, sum, expected)
