Severity
Low Risk
Description
Registering a new subscription involves updating the
subscriptionBySubscriber
mapping and appending the subscriber's address to the
subscribers
array. However, the
removeSubscription()
method solely removes the subscriber's address from the mapping, leaving potentially invalid subscriptions untouched within the storage array. This oversight, coupled with the absence of a subscription count limit, poses a vulnerability that could be exploited to initiate a Denial of Service (DoS) attack.
Location of Affected Code
File:
src/subscriptions/Initiator.sol#L46
----new code block----
/// @notice Removes a subscription for a subscriber
/// @param _subscriber Address of the subscriber
function removeSubscription(address _subscriber) public {
 require(msg.sender == _subscriber, "Only the subscriber can remove a subscription");
 delete subscriptionBySubscriber[_subscriber];
}
----end of code block ----
Proof of Concept
----new code block----
function testRemoveSubscription() public {
 address subscriber = address(1);
 uint256 amount = 1 ether;
 uint256 validUntil = block.timestamp + 30 days;
 uint256 paymentInterval = 10 days;
​
  vm.prank(subscriber);
  initiator.registerSubscription(subscriber, amount, validUntil, paymentInterval, address(token));
  vm.prank(subscriber);
  initiator.removeSubscription(subscriber);
​
  ISubExecutor.SubStorage memory sub = initiator.getSubscription(subscriber);
  assertEq(sub.subscriber, address(0));
​
 address[] memory registeredSubscribers = initiator.getSubscribers();
 bool isSubscriberPresent = false;
​
 for (uint i = 0; i < registeredSubscribers.length; i++) {
 if (registeredSubscribers[i] == subscriber) {
      isSubscriberPresent = true;
 break;
    }
  }
​
  assertFalse(isSubscriberPresent, "Subscriber should be removed from the subscriber's array");
}
----end of code block ----
Currently, the test above reverts with
Subscriber should be removed from the subscriber's array
.
----new code block----
Logs:
 Error: Subscriber should be removed from the subscriber's array
 Error: Assertion Failed
----end of code block ----
Recommendation
To address this vulnerability, change the code as follows:
File: Initiator.sol
----new code block----
+ mapping(address => bool) public isSubscriber;
+ mapping(address => uint256) public subscriberByIndex;
​
function registerSubscription(
  address _subscriber,
  uint256 _amount,
  uint256 _validUntil,
  uint256 _validAfter,
  uint256 _paymentInterval,
  address _erc20Token
) public {
  // code
​
+ if (!isSubscriber[_subscriber]) {
+   subscribers.push(_subscriber);
+   isSubscriber[_subscriber] = true;
+   subscriberByIndex[_subscriber] = subscribers.length - 1;
+ }
}
​
function removeSubscription(address _subscriber) public {
  require(msg.sender == _subscriber, "Only the subscriber can remove a subscription");
​
  delete subscriptionBySubscriber[_subscriber];
​
+ uint256 index = subscriberByIndex[_subscriber];
+ address lastSubscriber = subscribers[subscribers.length - 1];
+ subscribers[index] = lastSubscriber;
+ subscriberByIndex[lastSubscriber] = index;
+ subscribers.pop();
}
----end of code block ----
Team Response
Acknowledged and fixed as suggested.

Description:
DebtToken::flashLoan
fees can be bypassed by borrowing in small amounts to trigger
rounding down to zero
precision loss in fee calculation. Since this function allows re-entrancy, the function can be re-entered multiple times to borrow larger amounts with zero fee.
Impact:
Flash loan fees can be bypassed.
Proof of Concept:
Add following test contract to
test/foundry/core/DebtTokenTest.t.sol
:
----new code block----
// SPDX-License-Identifier: MIT
pragma solidity 0.8.19;
​
// test setup
import {TestSetup, DebtToken} from "../TestSetup.sol";
​
contract DebtTokenTest is TestSetup {
​
 function test_flashLoan() external {
 // entire supply initially available to borrow
        assertEq(debtToken.maxFlashLoan(address(debtToken)), type(uint256).max);
​
 // expected fee for borrowing 1e18
 uint256 borrowAmount = 1e18;
 uint256 expectedFee  = borrowAmount * debtToken.FLASH_LOAN_FEE() / 10000;
​
 // fee should be > 0
        assertTrue(expectedFee > 0);
​
 // fee should exactly equal
        assertEq(debtToken.flashFee(address(debtToken), borrowAmount), expectedFee);
​
 // exploit rounding down to zero precision loss to get free flash loans
 // by borrowing in small amounts
        borrowAmount = 1111;
        assertEq(debtToken.flashFee(address(debtToken), borrowAmount), 0);
​
 // as DebtToken::flashLoan allows re-entrancy, the function can be re-entered
 // multiple times to borrow larger amounts at zero fee
    }
}
----end of code block ----
Run with:
forge test --match-test test_flashLoan
Recommended Mitigation:
DebtToken::_flashFee
should revert if calculated fee is zero:
----new code block----
function _flashFee(uint256 amount) internal pure returns (uint256 fee) {
    fee = (amount * FLASH_LOAN_FEE) / 10000;
 require(fee > 0, "ERC20FlashMint: amount too small");
}
----end of code block ----
