Proof of Concept B
----new code block----
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import "forge-std/console.sol";
import {EVaultTestBase, EVault} from "./EVaultTestBase.t.sol";
import "../../../src/EVault/shared/types/Types.sol";
import "../../../src/EVault/shared/Constants.sol";
import "../../../src/EVault/shared/Events.sol";
​
contract POC_Test is EVaultTestBase {
 using TypesLib for uint256;
 event InterestAccrued(address indexed account, uint256 assets);
 address depositor = makeAddr("depositor");
 address borrower = makeAddr("borrower");
 address borrower2 = makeAddr("borrower_2");
​
 function setUp() public override {
 super.setUp();
        depositor = makeAddr("depositor");
        borrower = makeAddr("borrower");
        borrower2 = makeAddr("borrower_2");
 // Setup
        oracle.setPrice(address(assetTST), unitOfAccount, 1e18);
        oracle.setPrice(address(assetTST2), unitOfAccount, 1e18);
        eTST.setLTV(address(eTST2), 0.9e4, 0.9e4, 0);
 // Depositor
        startHoax(depositor);
        assetTST.mint(depositor, type(uint256).max);
        assetTST.approve(address(eTST), type(uint256).max);
        eTST.deposit(100e18, depositor);
 // Borrower
        startHoax(borrower);
        assetTST2.mint(borrower, type(uint256).max);
        assetTST2.approve(address(eTST2), type(uint256).max);
        eTST2.deposit(10e18, borrower);
        evc.enableCollateral(borrower, address(eTST2));
        evc.enableController(borrower, address(eTST));
        eTST.borrow(5e18, borrower);
        assertEq(assetTST.balanceOf(borrower), 5e18);
 // transferring some minted asset to borrower2
        assetTST2.transfer(borrower2, 10e18);
        vm.stopPrank();
        startHoax(borrower2);
 // deposit into eTST2 to cover the liability from pullDebt
        assetTST2.approve(address(eTST2), type(uint256).max);
        eTST2.deposit(10e18, borrower2);
        evc.enableCollateral(borrower2, address(eTST2));
        evc.enableController(borrower2, address(eTST));
        vm.stopPrank();
    }
​
 function test_POC() external {
 // accrue some interest so that there is dust in the owed
        skip(1 days);
 // borrow 1 wei so that user's interestAccumulator is updated
        startHoax(borrower);
        eTST.borrow(1, borrower);
        startHoax(borrower2);
        eTST.borrow(1, borrower2);
​
 // In the following TXs, the prevOwed from loadUserBorrow() should be equal to owed
 // therefore, InterestAccrued event should not be emitted, but it nevertheless does.
 uint256 currDebt = eTST.debtOf(borrower);
 // check that the unexpected InterestAccrued event is emitted
        vm.expectEmit();
 emit InterestAccrued(borrower, type(uint112).max);
        eTST.pullDebt(currDebt - 1, borrower);
        assertEq(eTST.debtOf(borrower), 0);
    }
}
----end of code block ----
The above proof of concept demonstrated that the
pullDebt
operation can emit an unexpected
InterestAccrued(_, type(uint112).max)
event.
Firstly, we use
skip(1 days)
to accrue a small amount of dust in the borrower's owed debt. Secondly, we borrow 1 wei for both the borrower and the repayer (i.e., borrower2) to update their
interestAccumulator
. This results in the
owed
and
owedPrev
values returned from
loadUserBorrow
being the same. Thus in this case, the subsequent
pullDebt
operation shouldn't emit the
InterestAccrued
event.
Then, we call
eTST.pullDebt(currDebt - 1, borrower)
. This should have the same effect as
eTST.pullDebt(currDebt, borrower)
or
eTST.pullDebt(type(uint256).max, borrower)
. However, as shown in the POC, it emits an unexpected
InterestAccrued(borrower, type(uint112).max)
event.
Recommendation
Compared to the convenience it brings to the user, the dust clean feature seems to cause more harm to the codebase.
It is recommended to remove this feature:
----new code block----
// If amount was rounded up, or dust is left over, transfer exact amount owed
----end of code block ----
to
----new code block----
// If amount was rounded up, transfer exact amount owed
----end of code block ----
----new code block----
if (
    (amount > fromOwed && amount.subUnchecked(fromOwed).isDust())
 || (amount < fromOwed && fromOwed.subUnchecked(amount).isDust())
) {
    amount = fromOwed;
}
----end of code block ----

Description:
As part of the implementation of the autonomous rebalance mechanism in
BunniHook::rebalanceOrderPreHook
, the hook balance of the order output token is set in transient storage before the order is executed. This occurs before the unlock callback, during which
hookHandleSwap()
is called within
_rebalancePrehookCallback()
:
----new code block----
 function rebalanceOrderPreHook(RebalanceOrderHookArgs calldata hookArgs) external override nonReentrant {
        ...
        RebalanceOrderPreHookArgs calldata args = hookArgs.preHookArgs;
​
 // store the order output balance before the order execution in transient storage
 // this is used to compute the order output amount
 uint256 outputBalanceBefore = hookArgs.postHookArgs.currency.isAddressZero()
            ? weth.balanceOf(address(this))
            : hookArgs.postHookArgs.currency.balanceOfSelf();
 assembly ("memory-safe") {
@>          tstore(REBALANCE_OUTPUT_BALANCE_SLOT, outputBalanceBefore)
        }
​
 // pull input tokens from BunniHub to BunniHook
 // received in the form of PoolManager claim tokens
 // then unwrap claim tokens
        poolManager.unlock(
 abi.encode(
                HookUnlockCallbackType.REBALANCE_PREHOOK,
@> abi.encode(args.currency, args.amount, hookArgs.key, hookArgs.key.currency1 == args.currency)
            )
        );
​
 // ensure we have at least args.amount tokens so that there is enough input for the order
@> if (args.currency.balanceOfSelf() < args.amount) {
 revert BunniHook__PrehookPostConditionFailed();
        }
        ...
    }
​
 /// @dev Calls hub.hookHandleSwap to pull the rebalance swap input tokens from BunniHub.
 /// Then burns PoolManager claim tokens and takes the underlying tokens from PoolManager.
 /// Used while executing rebalance orders.
 function _rebalancePrehookCallback(bytes memory callbackData) internal {
 // decode data
        (Currency currency, uint256 amount, PoolKey memory key, bool zeroForOne) =
 abi.decode(callbackData, (Currency, uint256, PoolKey, bool));
​
 // pull claim tokens from BunniHub
@>      hub.hookHandleSwap({key: key, zeroForOne: zeroForOne, inputAmount: 0, outputAmount: amount});
​
 // lock BunniHub to prevent reentrancy
        hub.lockForRebalance(key);
​
 // burn and take
        poolManager.burn(address(this), currency.toId(), amount);
        poolManager.take(currency, address(this), amount);
    }
----end of code block ----
The transient storage is again queried in the call to
rebalanceOrderPostHook()
to ensure that only the specified amount of the output token (consideration item) is transferred from
BunniHook
:
----new code block----
 function rebalanceOrderPostHook(RebalanceOrderHookArgs calldata hookArgs) external override nonReentrant {
        ...
        RebalanceOrderPostHookArgs calldata args = hookArgs.postHookArgs;
​
 // compute order output amount by computing the difference in the output token balance
 uint256 orderOutputAmount;
 uint256 outputBalanceBefore;
 assembly ("memory-safe") {
@>          outputBalanceBefore := tload(REBALANCE_OUTPUT_BALANCE_SLOT)
        }
 if (args.currency.isAddressZero()) {
 // unwrap WETH output to native ETH
            orderOutputAmount = weth.balanceOf(address(this));
            weth.withdraw(orderOutputAmount);
        } else {
            orderOutputAmount = args.currency.balanceOfSelf();
        }
@>      orderOutputAmount -= outputBalanceBefore;
        ...
----end of code block ----
However similar such validation is not applied to the input token (offer item). While the existing validation shown above is performed to ensure that the hook holds sufficient tokens to process the order, it fails to consider that the hook may hold funds designated to other recipients. Previously, per the Pashov Group finding H-04, autonomous rebalance was DoS’d by checking the token balance was strictly equal to the order amount but forgot to account for am-AMM fees and donations. The recommendation was to check that the contract’s token balance increase is equal to
args.amount
, not the total balance.
Given that am-AMM fees are stored as ERC-6909 balances within the
BunniHook
, these could be erroneously used as part of the rebalance order input amount. This could occur when the hook holds insufficient raw balance to cover the input amount, perhaps when rehypothecation is enabled and the
hookHandleSwap()
call pulls fewer tokens than expected due to the vault returning fewer tokens than specified. Instead, the input token balance should be set in transient storage before the unlock callback in the same way that
outputBalanceBefore
is. Then, the difference between the input token balances before the unlock callback and after should be validated to satisfy the order input amount.
Impact:
am-AMM fees stored as ERC-6909 balance inside
BunniHook
could be erroneously used as rebalance input due to the incorrect balance check.
Recommended Mitigation:
Consider modifying the validation performed after the unlock callback to:
----new code block----
uint256 inputBalanceBefore = args.currency.balanceOfSelf();
​
// unlock callback
​
if (args.currency.balanceOfSelf() - inputBalanceBefore < args.amount) {
 revert BunniHook__PrehookPostConditionFailed();
}
----end of code block ----
Bacon Labs:
Fixed in
PR #98
and
PR #133
.
Cyfrin:
Verified, stricter input amount validation has been added to
BunniHook::rebalanceOrderPreHook
.

Description:
Hooklets are intended to allow pool deployers to inject custom logic into various key pool operations such as initialization, deposits, withdrawals, swaps and Bunni token transfers.
To ensure that the hooklet invocations receive actual return values, all after operation hooks should be placed at the end of the corresponding functions; however,
BunniHubLogic::deposit
refunds excess ETH to users before the
hookletAfterDeposit()
call is executed which can result in cross-contract reentrancy when a user transfers Bunni tokens before the hooklet's state has updated:
----new code block----
 function deposit(HubStorage storage s, Env calldata env, IBunniHub.DepositParams calldata params)
 external
 returns (uint256 shares, uint256 amount0, uint256 amount1)
    {
        ...
 // refund excess ETH
 if (params.poolKey.currency0.isAddressZero()) {
 if (address(this).balance != 0) {
@>              params.refundRecipient.safeTransferETH(
                    FixedPointMathLib.min(address(this).balance, msg.value - amount0Spent)
                );
            }
        } else if (params.poolKey.currency1.isAddressZero()) {
 if (address(this).balance != 0) {
@>              params.refundRecipient.safeTransferETH(
                    FixedPointMathLib.min(address(this).balance, msg.value - amount1Spent)
                );
            }
        }
​
 // emit event
 emit IBunniHub.Deposit(msgSender, params.recipient, poolId, amount0, amount1, shares);
​
 /// -----------------------------------------------------------------------
 /// Hooklet call
 /// -----------------------------------------------------------------------
​
@>      state.hooklet.hookletAfterDeposit(
            msgSender, params, IHooklet.DepositReturnData({shares: shares, amount0: amount0, amount1: amount1})
        );
    }
----end of code block ----
This causes the
BunniToken
transfer hooks to be invoked on the Hooklet before notification of the deposit has concluded:
----new code block----
 function _beforeTokenTransfer(address from, address to, uint256 amount, address newReferrer) internal override {
        ...
 // call hooklet
 // occurs after the referral reward accrual to prevent the hooklet from
 // messing up the accounting
        IHooklet hooklet_ = hooklet();
 if (hooklet_.hasPermission(HookletLib.BEFORE_TRANSFER_FLAG)) {
@>          hooklet_.hookletBeforeTransfer(msg.sender, poolKey(), this, from, to, amount);
        }
    }
​
 function _afterTokenTransfer(address from, address to, uint256 amount) internal override {
 // call hooklet
        IHooklet hooklet_ = hooklet();
 if (hooklet_.hasPermission(HookletLib.AFTER_TRANSFER_FLAG)) {
@>          hooklet_.hookletAfterTransfer(msg.sender, poolKey(), this, from, to, amount);
        }
    }
----end of code block ----
Impact:
The potential impact depends on the custom logic of a given Hooklet implementation and its associated accounting.
Recommended Mitigation:
Consider moving the refund logic to after the
hookletAfterDeposit()
call. This ensures that the hooklet's state is updated before the refund is made, preventing the potential for re-entrancy.
Bacon Labs:
Fixed in
PR #120
.
Cyfrin:
Verified, the excess ETH refund in
BunniHubLogic::deposit
has been moved to after the Hooklet call.

The Mantra DEX attempts to protect against first depositor attacks by implementing a minimum liquidity mechanism, similar to that of Uniswap.
Before going further we can have an overview of the bug case here:
https://blog.openzeppelin.com/a-novel-defense-against-erc4626-inflation-attacks
https://mixbytes.io/blog/overview-of-the-inflation-attack
And we know that in order for this attack to be possible, two conditions need to be met:
Malicious user mint 1 mint of share.
Donate or transfer assets to the vault to inflate the assets per share.
However, the implementation has a flaw in how these minimum liquidity tokens that are expected to be used to protect against the 1 mint of share are stored/sent:
[/contracts/pool-manager/src/liquidity/commands.rs# L184-L213](https://github.com/code-423n4/2024-11-mantra-dex/blob/26714ea59dab7ecfafca9db1138d60adcf513588/contracts/pool-manager/src/liquidity/commands.rs# L184-L213)
----new code block----
​
 if total_share == Uint128::zero() {
 // Make sure at least MINIMUM_LIQUIDITY_AMOUNT is deposited to mitigate the risk of the first
 // depositor preventing small liquidity providers from joining the pool
                    let share = Uint128::new(
                        (U256::from(deposits[0].amount.u128())
                            .checked_mul(U256::from(deposits[1].amount.u128()))
                            .ok_or::<ContractError>(
                                ContractError::LiquidityShareComputationFailed,
                            ))?
                        .integer_sqrt()
                        .as_u128(),
                    )
                    .saturating_sub(MINIMUM_LIQUIDITY_AMOUNT);
​
 // share should be above zero after subtracting the MINIMUM_LIQUIDITY_AMOUNT
 if share.is_zero() {
 return Err(ContractError::InvalidInitialLiquidityAmount(
                            MINIMUM_LIQUIDITY_AMOUNT,
                        ));
                    }
​
                    messages.push(amm::lp_common::mint_lp_token_msg(
                        liquidity_token.clone(),
 &env.contract.address,
 &env.contract.address,
                        MINIMUM_LIQUIDITY_AMOUNT,
                    )?);
​
                    share
----end of code block ----
That’s to say in the case the case we have zero shares then we send the minimum liquidity amount to the contract instead of to the burn/dead address as is done in Uniswap.
This creates a vulnerability that could be exploited through the following steps:
Below we subtly assume that admin introduces a new functionality that could then allow for access to this contract owned tokens
.
Contract is migrated to a new version that allows owner to withdraw contract-owned LP tokens and allows for updating pool asset balance from direct transfers.
Owner withdraws the
MINIMUM_LIQUIDITY_AMOUNT
tokens from the contract.
Assume pool is not really active and we now have one user left.
User is malicious so they can withdraw all but one of their liquidity tokens.
Since
total_share
is not exactly zero but effectively zero, new deposits skip this check:
----new code block----
​
if total_share == Uint128::zero() {
 // Minimum liquidity check only happens on first deposit
 // But total_share is not zero, just very small
    ...
}
----end of code block ----
First depositor attack becomes possible again since minimum liquidity protection is bypassed.
Impact
Impact is quite high as we then are back open to first depositor attack, since after the user withdraws back and leaves just 1 share, the next depositor would receive a massively unfair exchange rate which allows the malicious user to backrun the tx and skew off these assets. Albeit, we have to classify as QA, considering currently there is no how we can access directly the minimum liquidity tokens, i.e., funds in the contract and it needs to be via an introduced function in an upgrade or some sort.
Would be key to note that asides the admin window we could still have an issue where there is a mismatch between the amount of pool assets and the amount of minted lp tokens; which is because when minting the lp tokens, we use the
checked_add
function, which does not overflow, so the last user that deposits and every that deposits to pass the maximum value would then cause a mismatch in the amount of pool assets and the amount of lp tokens minted:
[/contracts/pool-manager/src/liquidity/commands.rs# L376-L390](https://github.com/code-423n4/2024-11-mantra-dex/blob/26714ea59dab7ecfafca9db1138d60adcf513588/contracts/pool-manager/src/liquidity/commands.rs# L376-L390)
----new code block----
​
 // Increment the pool asset amount by the amount sent
 for asset in deposits.iter() {
            let asset_denom = &asset.denom;
            let pool_asset_index = pool_assets
                .iter()
                .position(|pool_asset| &pool_asset.denom == asset_denom)
                .ok_or(ContractError::AssetMismatch)?;
​
            pool_assets[pool_asset_index].amount = pool_assets[pool_asset_index]
                .amount
                .checked_add(asset.amount)?;
        }
​
        pool.assets = pool_assets.clone();
----end of code block ----
Recommended Mitigation Steps
Follow Uniswap’s approach of permanently burning minimum liquidity tokens, this can be done by using the same approach as to when liquidity is being withdrawn:
----new code block----
​
 // Burn the LP tokens
    messages.push(amm::lp_common::burn_lp_asset_msg(
        liquidity_token,
        env.contract.address,
        amount,
    )?);
----end of code block ----

Update Price Function Vulnerability
The
update_price
function lacks a proper implementation of throttling price updates, potentially allowing price manipulation by exploiting
CrankPriceHistories
. The
minimum_elapsed_slots
field is intended to serve as a throttling mechanism, preventing frequent updates to the price history by limiting the frequency of price updates to avoid abuse or manipulation.
Code Snippet
----new code block----
oracle_price_history/mod.rs
​
/// Push an update onto the historical prices array, using the appropriate
/// deserialization routine for the oracle type given by `self.oracle_type`.
pub fn update_price(
    &mut self,
    oracle_data: &[u8],
) -> Result<()> {
 let historical_price = match OracleType::from(self.oracle_type) {
        OracleType::Pyth => {
            HistoricalPrice::from_pyth_data(oracle_data)
        },
        OracleType::Switchboardv2 => {
            HistoricalPrice::from_switchboard_data(oracle_data)
        },
        _ => {
 return err!(SSLV2Error::InvalidOracleType);
        }
    }?;
    [...]
}
----end of code block ----
However, the function
update_price
currently doesn’t take into account the variable
minimum_elapsed_slots
. As a consequence, a user has the potential to manipulate the asset price by causing it to drop for a brief duration. Subsequently, they can exploit this situation by quickly executing the permissionless operation known as
minimum_elapsed_slots
. This operation involves processing a set of oracle and historical price accounts, updating the historical prices for each single-sided liquidity pool based on new oracle data. In this scenario, this unintended update can significantly decrease the token price in comparison to its initial value.
Remediation
Ensure
update_price
checks the elapsed slots since the last update and only allows updates if a sufficient number of slots have passed, as specified by
minimum_elapsed_slots
.
Patch
Fixed in commit
b87a933
.

Description:
BunniHub::hookHandleSwap
overestimates the reserves deposited to ERC-4626 vaults and assumes that within the call to
_updateVaultReserveViaClaimTokens()
it deposits enough to execute the swap:
----new code block----
 function hookHandleSwap(PoolKey calldata key, bool zeroForOne, uint256 inputAmount, uint256 outputAmount)
 external
 override
        nonReentrant
        notPaused(4)
    {
 if (msg.sender != address(key.hooks)) revert BunniHub__Unauthorized();
​
 // load state
        PoolId poolId = key.toId();
        PoolState memory state = getPoolState(s, poolId);
        (Currency inputToken, Currency outputToken) =
            zeroForOne ? (key.currency0, key.currency1) : (key.currency1, key.currency0);
        (uint256 initialReserve0, uint256 initialReserve1) = (state.reserve0, state.reserve1);
​
 // pull input claim tokens from hook
 if (inputAmount != 0) {
            zeroForOne ? state.rawBalance0 += inputAmount : state.rawBalance1 += inputAmount;
            poolManager.transferFrom(address(key.hooks), address(this), inputToken.toId(), inputAmount);
        }
​
 // push output claim tokens to hook
 if (outputAmount != 0) {
            (uint256 outputRawBalance, ERC4626 outputVault) =
                zeroForOne ? (state.rawBalance1, state.vault1) : (state.rawBalance0, state.vault0);
 if (address(outputVault) != address(0) && outputRawBalance < outputAmount) {
 // insufficient token balance
 // withdraw tokens from reserves
@>              (int256 reserveChange, int256 rawBalanceChange) = _updateVaultReserveViaClaimTokens(
                    (outputAmount - outputRawBalance).toInt256(), outputToken, outputVault
                );
                zeroForOne
                    ? (state.reserve1, state.rawBalance1) =
                        (_updateBalance(state.reserve1, reserveChange), _updateBalance(state.rawBalance1, rawBalanceChange))
                    : (state.reserve0, state.rawBalance0) =
                        (_updateBalance(state.reserve0, reserveChange), _updateBalance(state.rawBalance0, rawBalanceChange));
            }
@>          zeroForOne ? state.rawBalance1 -= outputAmount : state.rawBalance0 -= outputAmount;
            poolManager.transfer(address(key.hooks), outputToken.toId(), outputAmount);
        }
----end of code block ----
In the event the vault does not actually pull this amount of assets, it could cause raw balances to be considered smaller than they actually are:
----new code block----
 function _updateVaultReserveViaClaimTokens(int256 rawBalanceChange, Currency currency, ERC4626 vault)
 internal
 returns (int256 reserveChange, int256 actualRawBalanceChange)
    {
 uint256 absAmount = FixedPointMathLib.abs(rawBalanceChange);
 if (rawBalanceChange < 0) {
 uint256 maxDepositAmount = vault.maxDeposit(address(this));
 // if poolManager doesn't have enough tokens or we're trying to deposit more than the vault accepts
 // then we only deposit what we can
 // we're only maintaining the raw balance ratio so it's fine to deposit less than requested
 uint256 poolManagerReserve = currency.balanceOf(address(poolManager));
            absAmount = FixedPointMathLib.min(FixedPointMathLib.min(absAmount, maxDepositAmount), poolManagerReserve);
​
 // burn claim tokens from this
            poolManager.burn(address(this), currency.toId(), absAmount);
​
 // take tokens from poolManager
            poolManager.take(currency, address(this), absAmount);
​
 // deposit tokens into vault
            IERC20 token;
 if (currency.isAddressZero()) {
 // wrap ETH
                weth.deposit{value: absAmount}();
                token = IERC20(address(weth));
            } else {
                token = IERC20(Currency.unwrap(currency));
            }
 address(token).safeApproveWithRetry(address(vault), absAmount);
            reserveChange = vault.deposit(absAmount, address(this)).toInt256();
​
 // it's safe to use absAmount here since at worst the vault.deposit() call pulled less token
 // than requested
@>          actualRawBalanceChange = -absAmount.toInt256();
​
 // revoke token approval to vault if necessary
 if (token.allowance(address(this), address(vault)) != 0) {
 address(token).safeApprove(address(vault), 0);
            }
        } else if (rawBalanceChange > 0) {
            ...
        }
    }
----end of code block ----
Similarly, when attempting to surge to the target raw balance ratio, it is not guaranteed that the vault withdraws sufficient reserves to reach the target raw balance bounds.
BunniHub::_updateRawBalanceIfNeeded
attempts to reach target but this is not guaranteed:
----new code block----
 function _updateRawBalanceIfNeeded(
        Currency currency,
        ERC4626 vault,
 uint256 rawBalance,
 uint256 reserve,
 uint256 minRatio,
 uint256 maxRatio,
 uint256 targetRatio
    ) internal returns (uint256 newReserve, uint256 newRawBalance) {
 uint256 balance = rawBalance + getReservesInUnderlying(reserve, vault);
 uint256 minRawBalance = balance.mulDiv(minRatio, RAW_TOKEN_RATIO_BASE);
 uint256 maxRawBalance = balance.mulDiv(maxRatio, RAW_TOKEN_RATIO_BASE);
​
 if (rawBalance < minRawBalance || rawBalance > maxRawBalance) {
 uint256 targetRawBalance = balance.mulDiv(targetRatio, RAW_TOKEN_RATIO_BASE);
@>          (int256 reserveChange, int256 rawBalanceChange) =
                _updateVaultReserveViaClaimTokens(targetRawBalance.toInt256() - rawBalance.toInt256(), currency, vault);
            newReserve = _updateBalance(reserve, reserveChange);
            newRawBalance = _updateBalance(rawBalance, rawBalanceChange);
        } else {
            (newReserve, newRawBalance) = (reserve, rawBalance);
        }
    }
----end of code block ----
In this case, a vault accepting fewer assets than requested would result in an underestimate for the true raw balance. Assuming a deposit is successful but the actual amount pulled by the vault in
_depositVaultReserve()
is less than the
amountSpent
, this is the scenario that necessitates revocation of the token approval to the vault:
----new code block----
// revoke token approval to vault if necessary
if (token.allowance(address(this), address(vault)) != 0) {
 address(token).safeApprove(address(vault), 0);
}
----end of code block ----
While there does exist an excess ETH refund at the end of
BunniHubLogic::deposit
, this does not take into account any discrepancy due to the above behavior. Similarly, this is not accounted or refunded to the caller for ERC-20 tokens either. As such, these deltas corresponding to any unused WETH or other ERC-20 tokens will remain in the
BunniHub
. One such place this balance could be erroneously used is in the calculation of the rebalance order output amount in
BunniHook::rebalanceOrderPostHook
which uses the contract balance less the transient
outputBalanceBefore
. Thus, the fulfiller of an order executed via Flood Plain could erroneously benefit from this oversight.
----new code block----
 if (args.currency.isAddressZero()) {
 // unwrap WETH output to native ETH
@>      orderOutputAmount = weth.balanceOf(address(this));
        weth.withdraw(orderOutputAmount);
    } else {
        orderOutputAmount = args.currency.balanceOfSelf();
    }
@>  orderOutputAmount -= outputBalanceBefore;
----end of code block ----
While
rebalanceOrderPostHook()
intends to use the actual change in balance from the rebalance order execution based on the transient storage cache, any attempted nested deposit within the
_rebalancePrehookCallback()
that pulls fewer tokens than expected with contribute to the overall contract balance after the transient storage is set. Therefore,
orderOutputAmount
shown below will include this increased balance even after it is decremented by
outputBalanceBefore
:
----new code block----
 assembly ("memory-safe") {
            outputBalanceBefore := tload(REBALANCE_OUTPUT_BALANCE_SLOT)
        }
 if (args.currency.isAddressZero()) {
 // unwrap WETH output to native ETH
@>          orderOutputAmount = weth.balanceOf(address(this));
            weth.withdraw(orderOutputAmount);
        } else {
            orderOutputAmount = args.currency.balanceOfSelf();
        }
@>      orderOutputAmount -= outputBalanceBefore;
----end of code block ----
Additionally, other vault edge case behaviour does not appear to be sufficiently handled. Morpho is comprised of the core protocol
Morpho Blue
and then on top of that there are two versions of
MetaMorpho
. When fork testing against a USDC instance of
MetaMorphoV1_1
, it was observed to have a withdrawal queue length of 3 which specifies which markets to prioritise when withdrawing assets from the underlying protocol. Obtaining all the market ids allows the corresponding supply/borrow assets and shares to be queried. The significance of an error
NotEnoughLiquidity()
that was observed is that too much of the USDC is being actively lent out to allow withdrawals to be processed. This likely depends on how specific vaults and their markets are configured, but can be quite problematic for all core functionality.
Impact:
While the full impact is not currently completely clear, incorrect accounting due to edge cause vault behavior could result in a slight loss to users and DoS of core functionality due to unhandled reverts.
Recommended Mitigation:
Consider:
Explicitly handling the cases where vaults do not take the expected asset amounts.
Processing refunds to callers for any unused tokens.
Adding more sophisticated failover logic for vault calls that could unexpectedly revert.
Bacon Labs:
Fixed first point in
PR #128
. Acknowledge the point about swaps reverting when there’s not enough liquidity in the vault, there’s not much that we can do when this happens besides reverting (we could give less output tokens but the swap should revert due to the high slippage anyways).
Cyfrin:
Verified, the actual token balance change is now used as the raw balance change during deposit in
BunniHub::_updateVaultReserveViaClaimTokens
and any excess amounts are processed accordingly.

RemoveBlacklist Function Security Flaws
The
removeBlacklist
function removes the blacklisted address from the
inBlacklist
map but fails to remove the same address from the
blacklistAddresses
array.
----new code block----
// contracts/multiRewards/gamefi/base/MultiRewardsBasePoolV3.sol
function removeBlacklist(address _address) external onlyAdmin {
 require(
        inBlacklist[_address],
 "MultiRewardsBasePoolV3.removeBlacklist: address not in blacklist, please try to add first"
    );
    inBlacklist[_address] = false;
 /* abridged */
}
----end of code block ----
Security Implications
This implementation flaw has two security implications:
An oversized blacklist may lead to a denial of service condition in
adjustedTotalSupply
.
It allows duplicate entries to be present in the array. Redundant entries in the array may violate the invariant that ensures the sum of all blacklisted shares is less than or equal to the total supply. If this invariant is broken,
adjustedTotalSupply
is bound to revert due to integer overflow in the last subtraction.
----new code block----
// contracts/multiRewards/gamefi/base/MultiRewardsBasePoolV3.sol
function adjustedTotalSupply() public view returns (uint256) {
 uint256 blacklistSum = 0;
 for (uint256 i = 0; i < blacklistAddresses.length; i++) {
        blacklistSum = blacklistSum + blacklistAmount[blacklistAddresses[i]];
    }
 return super.totalSupply() - blacklistSum;
}
----end of code block ----
Remediation
Remove the
blacklistAddresses
array and maintain only the
blacklistSum
in a separate member variable.
Patch
Fixed in commits
8c37830
and
15e0843
.

Resolution
The client addressed this issue in commit
7ef2853d21049986beefaec4f2405814319f7cfb
. Additionally, they provided the following statement:
“The
fetchAllTicketCommentsCount()
method has been deleted and rebuilt from scratch. Its new name is
checkTicketUpdates
and the following improvements were added:
Improved performance (see 4.5 for more details)
Improved error handling
Early exit if some state variables are not available
Reduced the number of ‘then’ statements to reduce complexion and improve readability
Renamed function and variables for better readability”
Description
The current
fetchAllTicketCommentsCount()
function is overly complex and poorly optimized. For instance, the function unnecessarily exhibits a sequence of “then” promises, which could be avoided. Moreover, the function fetches ticket comments sequentially, whereas a parallel approach would be more efficient. It also parses
ticket_count
from the received JSON data and uses it to iterate over that data, yet it fails to validate that
ticket_count
is less than the length of the received data. These examples illustrate that it would be a good idea to refactor and optimize the function to increase the readability and robustness of its code.
We would suggest optimizing the function and simplifying its code to improve readability and robustness. More precisely, one could make the following changes:
Exit early if variables like
address
or
apiKey
are not initialized
Sanitize and validate relevant untrusted values, such as the
ticket_count
Refactor the data processing logic to be more succinct and readable. Consider using different data structures (e.g., objects) to simplify the logic and improve the robustness of the code.
Leverage parallel data fetching by utilizing
Promise.all()
to concurrently fetch ticket comments
Streamline the code by removing unnecessary chains of promises, logging, and verbose comments
Add proper error handling
