:
NAMESPACE = keccak256("com.lifi.facets.axelar"); // hex"c7...";
OwnershipFacet.sol
:
NAMESPACE = hex"cf...";
//
keccak256("com.lifi.facets.ownership");
Change to
:
NAMESPACE = keccak256("com.lifi.facets.ownership"); // hex"cf...";
PeripheryRegistryFacet.sol
:
NAMESPACE = hex"dd...";
//
keccak256("com.lifi.facets.periphery_registry");
Change to
:
NAMESPACE = keccak256("com.lifi.facets.periphery_registry"); // hex"dd...";
LibAccess.sol
:
ACCESS_MANAGEMENT_POSITION = hex"df...";
//
keccak256("com.lifi.library.access.management");
Change to
:
NAMESPACE = keccak256("com.lifi.library.access.management"); // hex"df...";
StargateFacet.sol
