CustomToken Transfer Acceptance Check
Context
CustomToken.sol#L246
Description
When safely transferring a registration to a contract, the underlying
CustomToken._doSafeTransferAcceptanceCheck(...)
method validates that the registration has been correctly received.
At first, the target contract's
onERC1155Received(...)
method is called. If it doesn't exist (external call fails), the
onERC721Received(...)
method is invoked in the catch block. This way, the protocol seamlessly covers safe transfers for ERC-1155 and ERC-721 receiver contracts.
Function
----new code block----
function _doSafeTransferAcceptanceCheck(
 address operator_,
 address from_,
 address to_,
 uint256 id_,
 uint256 amount_,
 bytes memory data_
) private {
 if (to_.isContract()) {
 try IERC1155Receiver(to_).onERC1155Received(operator_, from_, id_, amount_, data_) returns (bytes4 response) {
 if (response != IERC1155Receiver(to_).onERC1155Received.selector) {
 revert CustomToken_ERC1155ReceiverRejectedTokens();
            }
        } catch Error(string memory reason) {
 revert(reason);
        } catch {
 try IERC721Receiver(to_).onERC721Received(operator_, from_, id_, data_) returns (bytes4 response) {
 if (response != IERC721Receiver.onERC721Received.selector) {
 revert CustomToken_ERC721ReceiverRejectedTokens();
                }
            } catch Error(string memory reason) {
 revert(reason);
            } catch {
 revert CustomToken_NotTokenReceiver();
            }
        }
    }
}
----end of code block ----
Assume the following receiver contract which only supports ERC-721:
Has no
onERC1155Received(...)
method.
Has an
onERC721Received(...)
method.
Has a
fallback()
method.
Note that it’s a legitimate assumption that a user contract which implements the
ERC721Receiver
interface also has its own logic, methods, and likely a
fallback()
method.
What Will Happen on a Safe Transfer
The
CustomToken._doSafeTransferAcceptanceCheck(...)
method tries to call
onERC1155Received(...)
, which doesn’t exist. Therefore, the
fallback()
method is executed and returns nothing (return data has length 0) on success.
Note that the try-catch is not triggered in the case of a successful call, and the empty return data is going to be decoded to
bytes4
, see @audit comment in the above code, which leads to an uncaught
EvmError
(see the proof of concept).
If the
fallback()
method reverts with an error message, it’s simply forwarded. In both cases, the invocation of
onERC721Received(...)
will never be tried.
Impact
Any safe registration transfer to a contract that only supports ERC-721 and happens to have a
fallback()
method will inevitably fail.
Proof of Concept
Add the following test file
CustomToken.t.sol
to the codebase and run the test case with
forge test -vv --match-test testTransferCallback
:
----new code block----
// SPDX-License-Identifier: UNLICENSED
pragma solidity ~0.8.18;
​
import {DomainController} from "src/regcontrol/modules/DomainController.sol";
import {IERC721Receiver} from "src/regcontrol/interfaces/tokens/IERC721.sol";
import "forge-std/Test.sol";
​
contract TestCustomToken is Test, DomainController {
 bool public received;
​
 function onERC721Received(address, address, uint256, bytes calldata) external returns (bytes4) {
        received = true;
 return IERC721Receiver.onERC721Received.selector;
    }
​
 // gets called instead of 'onERC1155Received' and returns nothing
 fallback() external {
 // do something ... and return, or:
 // revert("alternative PoC");
    }
​
 function testTransferCallback() public {
        _transfer__callback(address(this), address(this), 0, hex"");
 // fails with 'EvmError' due to trying to decode empty return data from fallback to 'bytes4'
        assertTrue(received);
    }
}
----end of code block ----
Recommendation
I recommend the following alternative implementation of
CustomToken._doSafeTransferAcceptanceCheck(...)
which keeps the intended functionality and error message forwarding, but resolves the present issue, no matter if the
fallback()
method returns or reverts.
Please review this code with respect to the inline comments in order to get the best understanding.
Updated Function
----new code block----
function _doSafeTransferAcceptanceCheck(
 address operator_,
 address from_,
 address to_,
 uint256 id_,
 uint256 amount_,
 bytes memory data_
) private {
 if (to_.isContract()) {
 /* ERC1155 handling */
        (bool success1, bytes memory data1) = to_.call(abi.encodeCall(IERC1155Receiver.onERC1155Received, (operator_, from_, id_, amount_, data_)));
​
 if (success1 && data1.length != 0) { // success AND has return data
 if (abi.decode(data1, (bytes4)) != IERC1155Receiver.onERC1155Received.selector) {
 revert CustomToken_ERC1155ReceiverRejectedTokens();
            }
        } else { // failure OR no return data: fallback OR low-level failure (without error message) OR high-level error message
 /* ERC721 handling */
            (bool success2, bytes memory data2) = to_.call(abi.encodeCall(IERC721Receiver.onERC721Received, (operator_, from_, id_, data_)));
​
 if (data2.length != 0) { // has return data
 if (success2) { // success -> check return data
 if (abi.decode(data2, (bytes4)) != IERC721Receiver.onERC721Received.selector) {
 revert CustomToken_ERC721ReceiverRejectedTokens();
                    }
                } else { // failure -> forward error message
 /// @solidity memory-safe-assembly
 assembly {
 revert(add(32, data2), mload(data2))
                    }
                }
            } else { // no return data: failure without error message -> forward previous error message
 if (data1.length != 0) {
 /// @solidity memory-safe-assembly
 assembly {
 revert(add(32, data1), mload(data1))
                    }
                } else {
 revert CustomToken_NotTokenReceiver();
                }
            }
        }
    }
}
----end of code block ----

Resolution
The following changeset is addressing this issue by being more strict on type and input validation:
fort-major/msq@
26a0eec
Description
The functions
getBaseEntropy
and
getSignIdentity
lack validation for the correct type of arguments or the presence of control characters that may allow context breaks (newline).
For example, in the
SNAP_METHODS.public.identity.requestLink
method handler, the
body.withOrigin
is unsanitized and concatenated directly for the resulting salt.
withOrigin
is a user provided value and may include
\n
which breaks the context of the salt structure.
Examples
packages/snap/src/utils.ts:L75-L89
----new code block----
export async function getSignIdentity(
 origin: TOrigin,
 identityId: TIdentityId,
 salt: Uint8Array,
): Promise<Secp256k1KeyIdentity> {
 // the MSQ site has constant origin
 // this will allow us to change the domain name without users losing their funds and accounts
 const orig = isMsq(origin) ? "https://msq.tech" : origin;
​
 // shared prefix may be used in following updates
 const entropy = await getEntropy(orig, identityId, "identity-sign\nshared", salt);
​
 return Secp256k1KeyIdentity.fromSecretKey(entropy);
}
​
----end of code block ----
packages/snap/src/utils.ts:L105-L115
----new code block----
async function getBaseEntropy(origin: TOrigin, identityId: TIdentityId, internalSalt: string): Promise<Uint8Array> {
 const generated: string = await snap.request({
 method: "snap\_getEntropy",
 params: {
 version: 1,
 salt: `\x0amsq-snap\n${origin}\n${identityId}\n${internalSalt}`,
 },
 });
​
 return hexToBytes(generated.slice(2));
}
​
----end of code block ----
Recommendation
To address this, enforcing that
identityId
is a positive number, valid id and
origin
is a valid URL (free from control characters) would mitigate misuse of this functionality.

Based on the current implementation, when the protocol wants to use Chainlink oracle data feed for getting a collateral token's price, the fixed price for the token should not be set. When the fixed price is not set for the token, calling the
Oracle
contract's
viewPrice
or
getPrice
function will execute
uint price = feeds[token].feed.latestAnswer()
. As
https://blog.openzeppelin.com/secure-smart-contract-guidelines-the-dangers-of-price-oracles/
mentions, it is possible that Chainlink’s "multisigs can immediately block access to price feeds at will". When this occurs, executing
feeds[token].feed.latestAnswer()
will revert so calling the
viewPrice
and
getPrice
functions also revert, which cause denial of service when calling functions like
getCollateralValueInternal
and
getWithdrawalLimitInternal
. The
getCollateralValueInternal
and
getWithdrawalLimitInternal
functions are the key elements to the core functionalities, such as borrowing, withdrawing, force-replenishing, and liquidating; with these functionalities facing DOS, the protocol's usability becomes very limited.
https://github.com/code-423n4/2022-10-inverse/blob/main/src/Oracle.sol#L78-L105
----new code block----
 function viewPrice(address token, uint collateralFactorBps) external view returns (uint) {
 if(fixedPrices[token] > 0) return fixedPrices[token];
 if(feeds[token].feed != IChainlinkFeed(address(0))) {
 // get price from feed
 uint price = feeds[token].feed.latestAnswer();
 require(price > 0, "Invalid feed price");
 // normalize price
 uint8 feedDecimals = feeds[token].feed.decimals();
 uint8 tokenDecimals = feeds[token].tokenDecimals;
 uint8 decimals = 36 - feedDecimals - tokenDecimals;
 uint normalizedPrice = price * (10 ** decimals);
 uint day = block.timestamp / 1 days;
 // get today's low
 uint todaysLow = dailyLows[token][day];
 // get yesterday's low
 uint yesterdaysLow = dailyLows[token][day - 1];
 // calculate new borrowing power based on collateral factor
 uint newBorrowingPower = normalizedPrice * collateralFactorBps / 10000;
 uint twoDayLow = todaysLow > yesterdaysLow && yesterdaysLow > 0 ? yesterdaysLow : todaysLow;
 if(twoDayLow > 0 && newBorrowingPower > twoDayLow) {
 uint dampenedPrice = twoDayLow * 10000 / collateralFactorBps;
 return dampenedPrice < normalizedPrice ? dampenedPrice: normalizedPrice;
            }
 return normalizedPrice;
​
        }
 revert("Price not found");
    }
----end of code block ----
https://github.com/code-423n4/2022-10-inverse/blob/main/src/Oracle.sol#L112-L144
----new code block----
 function getPrice(address token, uint collateralFactorBps) external returns (uint) {
 if(fixedPrices[token] > 0) return fixedPrices[token];
 if(feeds[token].feed != IChainlinkFeed(address(0))) {
 // get price from feed
 uint price = feeds[token].feed.latestAnswer();
 require(price > 0, "Invalid feed price");
 // normalize price
 uint8 feedDecimals = feeds[token].feed.decimals();
 uint8 tokenDecimals = feeds[token].tokenDecimals;
 uint8 decimals = 36 - feedDecimals - tokenDecimals;
 uint normalizedPrice = price * (10 ** decimals);
 // potentially store price as today's low
 uint day = block.timestamp / 1 days;
 uint todaysLow = dailyLows[token][day];
 if(todaysLow == 0 || normalizedPrice < todaysLow) {
                dailyLows[token][day] = normalizedPrice;
                todaysLow = normalizedPrice;
 emit RecordDailyLow(token, normalizedPrice);
            }
 // get yesterday's low
 uint yesterdaysLow = dailyLows[token][day - 1];
 // calculate new borrowing power based on collateral factor
 uint newBorrowingPower = normalizedPrice * collateralFactorBps / 10000;
 uint twoDayLow = todaysLow > yesterdaysLow && yesterdaysLow > 0 ? yesterdaysLow : todaysLow;
 if(twoDayLow > 0 && newBorrowingPower > twoDayLow) {
 uint dampenedPrice = twoDayLow * 10000 / collateralFactorBps;
 return dampenedPrice < normalizedPrice ? dampenedPrice: normalizedPrice;
            }
 return normalizedPrice;
​
        }
 revert("Price not found");
    }
----end of code block ----
