Resolution
Fixed in
commit 0d22c5326e21541df0c718db98004d5a475aa2ea
by allowing only owners to perform the execution of approved transactions.
Description
The
execTransaction
function in the Multisig contract allows any address to execute the function, provided the transaction is approved by the required threshold number of owners of the Multisig contract. The
checkApprovals
function checks if the transaction data hash (
txHash
) has enough approvals, if so the
execTransaction
proceeds to execute the transaction. This behavior deviates from the Gnosis Safe’s implementation which requires that only the transaction approver can execute the transaction. This deviation may introduce some unknown risks to the system. Additionally the behavior also is inconsistent with the
documentation
of the Multisig contract which states
The last signer initiates the transaction
Examples
contracts/Multisig.sol:L382-L437
----new code block----
function execTransaction(
 address to,
 uint256 value,
 bytes calldata data,
    Operation operation,
 uint256 safeTxGas,
 uint256 baseGas,
 uint256 gasPrice,
 address gasToken,
 address payable refundReceiver
) public payable virtual returns (bool success) {
 bytes32 txHash;
 // use scope here to limit variable lifetime and prevent `stack too deep` errors
    {
 bytes memory txHashData = encodeTransactionData(
 // transaction info
            to,
            value,
            data,
            operation,
            safeTxGas,
 // payment info
            baseGas,
            gasPrice,
            gasToken,
            refundReceiver,
 // signature info
            nonce
        );
 // increase nonce and execute transaction.
        nonce++;
        txHash = keccak256(txHashData);
        checkApprovals(txHash, txHashData);
    }
 // we require some gas to emit the events (at least 2500) after the execution and some to perform code until the execution (500)
 // we also include the 1/64 in the check that is not send along with a call to counteract potential shortings because of EIP-150
 require(gasleft() >= max((safeTxGas * 64) / 63, safeTxGas + 2500) + 500, "Insufficient gas");
 // use scope here to limit variable lifetime and prevent `stack too deep` errors
    {
 uint256 gasUsed = gasleft();
 // if the gasPrice is 0 we assume that nearly all available gas can be used (it is always more than safeTxGas)
 // we only substract 2500 (compared to the 3000 before) to ensure that the amount passed is still higher than safeTxGas
        success = execute(to, value, data, operation, gasPrice == 0 ? (gasleft() - 2500) : safeTxGas);
        gasUsed = gasUsed - gasleft();
 // if no safeTxGas and no gasPrice was set (e.g. both are 0), then the internal tx is required to be successful
 // this makes it possible to use `estimateGas` without issues, as it searches for the minimum gas where the tx doesn't revert
 require(success || safeTxGas != 0 || gasPrice != 0, "Error during call");
 // we transfer the calculated tx costs to the tx.origin to avoid sending it to intermediate contracts that have made calls
 uint256 payment = 0;
 if (gasPrice > 0) {
            payment = handlePayment(gasUsed, baseGas, gasPrice, gasToken, refundReceiver);
        }
 if (success) emit ExecutionSuccess(txHash, payment);
 else emit ExecutionFailure(txHash, payment);
    }
}
​
----end of code block ----
