function priceUpdate() public override {
 if (collateralsCount < 2) {
 return;
    }
 for (uint256 i = 1; i < collateralsCount; ) {
        IOracle(collateralParams[collateralSupport[i]].oracle).fetchPrice();
 unchecked {
            i++;
        }
    }
}
