+    uint256 newGaugeWeight = oldGaugeWeight + newContribution - oldContribution;
----end of code block ----
Additional Recommendations
Use Dynamic Voting Power:
Replace calls to
veRAACToken.balanceOf(msg.sender)
with a function such as
getVotingPower(msg.sender, block.timestamp)
that factors in decay.
Implement SafeMath:
Ensure that all arithmetic operations use safe math (or Solidity 0.8+ built-in overflow checks) to prevent underflow/overflow errors.
By incorporating these changes, the gauge weight update will correctly reflect both the change in vote weight and the delta in voting power, ensuring accurate reward distribution and robust governance functionality.

WildcatMarketControllerFactory Line 138
Issue Description
The
getDeployedControllers()
function takes a start and end index of the controllers to be retrieved. However, due to the current implementation of the function, it only returns controllers from the start index to
end-1
. In other words, the controller at the
end
index is not included in the returned list.
POC
This simple POC can be added to the
WIldcatMarketController
test to check for the issue.
----new code block----
function test_getControllers() external {
//Deploy 10 contracts
 for(uint256 i = 0; i < 10; i++)
	{
		controllerFactory.deployController();
	}

 //Want to access 2-7 (6 controllers)
 address[] memory controllers = controllerFactory.getDeployedControllers(2, 7);

 //Check that the length is correct
 require(controllers.length == 5, "We have not received an incorrect number");

 //We only received controllers 2-6 due to the implementation
}
----end of code block ----
The same issue also exists in the functions:
WildcatMarketController.getAuthorizedLenders()
WildcatMarketController.getControlledMarkets()
WildcatArchController.getRegisteredBorrowers()
WildcatArchController.getRegisteredControllerFactories()
WildcatArchController.getRegisteredControllers()
WildcatArchController.getRegisteredMarkets()
Recommended Mitigation Steps
To resolve this issue, the
getDeployedControllers()
function should be rewritten as follows:
----new code block----
function getDeployedControllers(
uint256 start,
uint256 end
) external view returns (address[] memory arr) {
 uint256 len = _deployedControllers.length();
	end = MathUtils.min(end, len-1);
 uint256 count = end - start + 1;
	arr = new address[](count);
 for (uint256 i = 0; i < count; i++) {
		arr[i] = _deployedControllers.at(start + i);
	}
}
----end of code block ----
The same change should be applied to other affected functions as well.

Description:
The current implementation uses
_safeMint
before modifying state variables:
withdrawalRequests[tokenId]
exitingETH
_lastTokenIdCreated
This allows possible re-entrancy where the receiver and access the non-updated state variables. While during the audit no meaningful permissionless attack vectors related to this issue were found, to follow best security practices it is advisable to move
_safeMint
to the end of the function:
----new code block----
  function createWithdrawRequest(
    uint256 amount
  ) external override checkWhitelist(msg.sender) {
    if (AccessControlManager.withdrawalsPaused()) {
      revert WithdrawalsPaused();
    }
​
    if (amount < withdrawRequestMinimum) {
      revert WithdrawRequestTooSmall(amount, withdrawRequestMinimum);
    }
​
    if (amount > withdrawRequestMaximum) {
      revert WithdrawRequestTooLarge(amount, withdrawRequestMaximum);
    }
​
    IswETH swETH = AccessControlManager.swETH();
    swETH.transferFrom(msg.sender, address(this), amount);
​
    // Burn the tokens first to prevent reentrancy and to validate they own the requested amount of swETH
    swETH.burn(amount);
​
-   uint256 tokenId = _lastTokenIdCreated + 1; // Start off at 1
+   uint256 tokenId = ++_lastTokenIdCreated; // Starts off at 1
​
-   _safeMint(msg.sender, tokenId);
​
    uint256 lastTokenIdProcessed = getLastTokenIdProcessed();
​
    uint256 rateWhenCreated = AccessControlManager.swETH().swETHToETHRate();
​
    withdrawalRequests[tokenId] = WithdrawRequest({
      amount: amount,
      timestamp: block.timestamp,
      lastTokenIdProcessed: lastTokenIdProcessed,
      rateWhenCreated: rateWhenCreated
    });
​
    exitingETH += wrap(amount).mul(wrap(rateWhenCreated)).unwrap();
-   _lastTokenIdCreated = tokenId;
+   _safeMint(msg.sender, tokenId);
​
    emit WithdrawRequestCreated(
      tokenId,
      amount,
      block.timestamp,
      lastTokenIdProcessed,
      rateWhenCreated,
      msg.sender
    );
​
  }
