Description
The current implementation of the
get_earliest_proposed_state_update
function in the Rollman component contains excessive logging, which could potentially lead to performance issues or even a denial of service (DoS) scenario. The function logs detailed information for each iteration of its search process, including large data structures, which can result in:
Increased CPU usage due to frequent logging operations.
----new code block----
#[named]
async fn get_earliest_proposed_state_update(&self) -> Result<Option<(U256, StateUpdateFacts)>> {
 // Read STEP blocks at a time.
 const STEP: u64 = 100;
 let start_block = self
        .contract_genesis_block_number()
        .as_number()
        .unwrap()
        .as_u64();
 let exclusive_end_block = self.get_latest_block_num().await? + 1;
 assert!(start_block <= exclusive_end_block);
 let finalized_state_info = self.get_finalized_state(exclusive_end_block - 1).await?;
 let contract = NordOperatorFacet::new(self.get_proxy_address(), self.get_client());

    tracing::info!(
 "get_earliest_proposed_state_update SCAN ({:#x}..={:#x}) -> ActionID {:#x}",
        start_block,
        exclusive_end_block - 1,
        finalized_state_info.ending_action_id + 1
    );
​
 let earliest_proposal = 'earliest_prop: {
 for chunk in (start_block..exclusive_end_block).chunks(STEP).rev() {
            update_call_metric!();
 let mut sc_logs: Vec<PendingStateUpdateSubmittedFilter> = contract
                .event()
                .from_block(chunk.start)
                .to_block(chunk.end - 1)
                .query()
                .await?;
 if sc_logs.is_empty() {
 continue;
            }
 // See function documentation
            sc_logs.sort_by_key(|a| a.block_id);
            tracing::trace!(?sc_logs);

 // Stopping condition
 if let Some(_highest_step_block_id) = sc_logs
                .last()
                .filter(|x| x.block_id < U256::from(finalized_state_info.block_id))
            {
                tracing::info!("Finalizing: No proposal eligible for finalizing");
 break;
            }
 // NOTE: its "find()" which is intentionally a linear scan,
 // don't pattern match it with the sort above which is on a different key!
 // 
 // NOTE: its "rev()" which is intentionally a linear scan from end!
 if let Some(x) = sc_logs
                .iter()
                .rev()
                .find(|l| {
                    l.submittal.starting_action_id == finalized_state_info.ending_action_id + 1
                })
                .map(|x| (x.block_id, x.submittal.clone()))
            {
 break 'earliest_prop Some(x);
            }
        }
 None
    };
​
    tracing::info!(
 "get_earliest_proposed_state_update SCAN_END ({:#x}..={:#x}) -> {:#x?}",
        start_block,
        exclusive_end_block - 1,
        earliest_proposal
    );

 Ok(earliest_proposal)
}
----end of code block ----
Recommendation
Reduce the frequency and verbosity of logging within the function:
Remove the
tracing::trace!(?sc_logs);
line to avoid logging large data structures.
