  const AaveDIVAWrapper =
    await hre.ethers.getContractFactory("AaveDIVAWrapper");
  const aaveDIVAWrapper = await AaveDIVAWrapper.deploy(
@>  AAVE_V3_POOL,
@>  DIVA,
    OWNER,
  );
