​
 function _handleProtocolFee(uint256 amount) internal returns (uint256) {
 address feeTo = ROUTER().feeTo();
 bool feeOn = feeTo != address(0);
 if (feeOn) {
 uint256 fee = ROUTER().getProtocolFee(amount);
​
 unchecked {
        amount -= fee;
      }
      ERC20(asset()).safeTransfer(feeTo, fee);
    }
 return amount;
  }
