 uint256 t0DebtInAuction = poolBalances.t0DebtInAuction;
​
 if (result.t0DebtPenalty != 0) {
            t0PoolDebt      += result.t0DebtPenalty;
            t0DebtInAuction += result.t0DebtPenalty;
