impl TryFrom<pb::RoutingTable> for RoutingTable {
 type Error = ProxyDecodeError;
​
 fn try_from(src: pb::RoutingTable) -> Result<Self, Self::Error> {
 let mut map = BTreeMap::new();
 for entry in src.entries {
 let range = try_from_option_field(entry.range, "RoutingTable::Entry::range")?;
 let subnet_id = subnet_id_try_from_protobuf(entry.subnet_id.unwrap())?;
 if let Some(prev_subnet_id) = map.insert(range, subnet_id) {
 return Err(ProxyDecodeError::DuplicateEntry {
                    key: format!("{:?}", range),
                    v1: prev_subnet_id.to_string(),
                    v2: subnet_id.to_string(),
                });
            }
        }
 Ok(Self(map))
    }
}
----end of code block ----
Figure 32.5: The conversion code for RoutingTable (dfinity/rs/registry/routing_table/src/proto.rs)
----new code block----
impl TryFrom<pb_metadata::NetworkTopology> for NetworkTopology {
 type Error = ProxyDecodeError;
​
 fn try_from(item: pb_metadata::NetworkTopology) -> Result<Self, Self::Error> {
 let mut subnets = BTreeMap::<SubnetId, SubnetTopology>::new();
 for entry in item.subnets {
            subnets.insert(
 subnet_id_try_from_protobuf(try_from_option_field(
                    entry.subnet_id,
 "NetworkTopology::subnets::K",
                )?)?,
 try_from_option_field(
                    entry.subnet_topology,
 "NetworkTopology::subnets::V")?,
            );
        }
 // NetworkTopology.nns_subnet_id will be removed in the following PR
 // Currently, initialise nns_subnet_id with dummy value in case not found
 let nns_subnet_id =
 match try_from_option_field(item.nns_subnet_id, "NetworkTopology::nns_subnet_id") {
 Ok(subnet_id) => subnet_id_try_from_protobuf(subnet_id).unwrap(),
 Err(_) => SubnetId::new(PrincipalId::new_anonymous()),
            };
 Ok(Self {
            subnets,
            routing_table: try_from_option_field(
                item.routing_table,
 "NetworkTopology::routing_table",
            )?,
            nns_subnet_id,
        })
    }
}
----end of code block ----
Figure 32.6: The conversion code for NetworkTopology (dfinity/rs/replicated_state/src/metadata_state.rs)
----new code block----
/// From its protobuf definition convert to a SubnetId.  Normally, we would
/// use `impl TryFrom<pb::SubnetId> for SubnetId` here however we cannot as
/// both `Id` and `pb::SubnetId` are defined in other crates.
pub fn subnet_id_try_from_protobuf(
    value: pb::SubnetId,
) -> Result<SubnetId, PrincipalIdBlobParseError> {
 // All fields in Protobuf definition are required hence they are encoded in
 // `Option`. We simply treat them as required here though.
 let principal_id = PrincipalId::try_from(value.principal_id.unwrap())?;
 Ok(SubnetId::from(principal_id))
}
----end of code block ----
Figure 32.7: The conversion code for SubnetId (dfinity/rs/types/base_types/src/lib.rs)
Exploit Scenario
An attacker crafts and sends messages that cannot be deserialized. This causes the process to crash, resulting in a denial of service (and may not be detected by honest nodes).
Recommendations
Short term, fix the
TryFrom
trait implementations and other conversion functions mentioned in this finding so that they will not panic when provided malformed input.
Long term, avoid using panicking functions such as
Option::unwrap()
and
Result::unwrap()
. Instead, use an explicit method of error handling, such as pattern matching. This type of method will leverage Rust's type system to identify places in which operations could fail.

Severity
Impact:
Medium
Likelihood:
Medium
Description
The
depositVault
allows unlimited deposits per funding period without any cap, which can lead to a DoS scenario during the execution of
DepositProcess.processDeposit()
, if too much liquidity is deposited into the
depositVault
during a single period, it can result in the vault attempting to hedge a larger position than what the GammaSwap pool can support, causing the
IGammaPool(gsPool).borrowLiquidity()
call to revert.
----new code block----
function _increaseHedge(
 uint256 _liquidity,
 bytes memory path0,
 bytes memory path1
    ) internal virtual {
 //...
 uint256 _hedgeLpTokens = GSHedgeMath.convertLiquidityToLPTokens(
            cfmm,
            _liquidity
        );
​
         IGammaPool(gsPool).borrowLiquidity(
            _gsTokenId,
            _hedgeLpTokens,
 new uint256[](0)
        ); // use externalRebalancing here or hedge with internal AMM
​
        _updateHedge(path0, path1, s.ratio0, s.ratio1);
    }
​
----end of code block ----
The
_hedgeLpTokens
amount is calculated using the ratio between the Uniswap pool's total liquidity and LP token supply:
----new code block----
 function convertLiquidityToLPTokens(
 address _cfmm,
 uint256 _liquidity
    ) internal view returns (uint256) {
        (uint128 reserve0, uint128 reserve1, ) = ICPMM(_cfmm).getReserves();
 uint256 lastCFMMInvariant = GSMath.sqrt(reserve0 * reserve1);
 uint256 lastCFMMTotalSupply = GammaSwapLibrary.totalSupply(_cfmm);
 return (_liquidity * lastCFMMTotalSupply) / lastCFMMInvariant;
    }
----end of code block ----
and the
IGammaPool(gsPool).borrowLiquidity()
function will revert if the requested LP tokens exceed the pool's available balance (
s.LP_TOKEN_BALANCE
):
----new code block----
function borrowLiquidity(uint256 tokenId, uint256 lpTokens, uint256[] calldata ratio) external virtual override whenNotPaused(12) returns(uint256 liquidityBorrowed, uint256[] memory amounts, uint128[] memory tokensHeld) {
 return abi.decode(callStrategy(borrowStrategy, abi.encodeCall(IBorrowStrategy._borrowLiquidity, (tokenId, lpTokens, ratio))), (uint256, uint256[], uint128[]));
 }
​
//...
/// @dev See {IBorrowStrategy-_borrowLiquidity}.
 function _borrowLiquidity(uint256 tokenId, uint256 lpTokens, uint256[] calldata ratio) external virtual override lock returns(uint256 liquidityBorrowed, uint256[] memory amounts, uint128[] memory tokensHeld) {
 // Revert if borrowing all CFMM LP tokens in pool
 if(lpTokens >= s.LP_TOKEN_BALANCE) revert ExcessiveBorrowing();
 //...
 }
----end of code block ----
Exceeding the GammaSwap pool's
s.LP_TOKEN_BALANCE
could be achieved in two ways:
The
processDeposit()
transaction can be frontrun by a malicious actor (as the protocol will be deployed on Ethereum) by depositing a large ETH amount (by a flash-loan), so that the required lp tokens needed to borrow to increase the hedge would be inflated to exceed the GammaSwap pool balance
s.LP_TOKEN_BALANCE
.
If users naturally deposit large amounts during the same funding period.
Recommendations
Implement a deposit cap per period where the
depositVault
can't receive any further deposits from users when it's reached.
Update the
convertLiquidityToLPTokens()
calculation to ensure the requested LP tokens (
_hedgeLpTokens
) do not exceed the GammaSwap pool's
s.LP_TOKEN_BALANCE
.

Severity
Medium Risk
Description
In order for the Smart Wallets to use
CredibleAccountModule
as a Hook, they call
onInstall()
and install it as a Hook.
----new code block----
function onInstall(bytes calldata data) external override {
 // code
 if (moduleType == MODULE_TYPE_VALIDATOR) { ... }
 else if (moduleType == MODULE_TYPE_HOOK) {
>>      moduleInitialized[msg.sender].hookInitialized = true;
    } else {
 revert CredibleAccountModule_InvalidModuleType();
    }
}
----end of code block ----
When executing the tx on
ModularEtherspotWallet
, we call it with the
withHook()
modifier. and since this hook can be installed. The wallet will call
preCheck()
before execution and call
postCheck()
after execution.
----new code block----
modifier withHook() {
 address hook = _getHook();
 if (hook == address(0)) {
 _;
    } else {
 bytes memory hookData = IHook(hook).preCheck(
 msg.sender,
 msg.value,
 msg.data
        );
 _;
        IHook(hook).postCheck(hookData);
    }
}
​
// -----
​
function execute( ... ) external payable onlyEntryPointOrSelf withHook { ... }
----end of code block ----
But in
CredibleAccountModule
, there is no checking whether the
msg.sender
is initialising that Hook or not:
----new code block----
function preCheck(address msgSender, uint256 msgValue, bytes calldata msgData) external override returns (bytes memory hookData) {
    (address sender,) = abi.decode(msgData, (address, bytes));
 return abi.encode(sender, _cumulativeLockedForWallet(sender));
}
​
// -----
​
function postCheck(bytes calldata hookData) external {
 // code
}
----end of code block ----
This will make any wallet either a Modular wallet or a Smart wallet, call these functions, allowing them to change the
liveness
of the session keys of other users, breaking the access control of the Locking token mechanism.
Location of Affected Code
File:
src/modules/validators/CredibleAccountModule.sol
Impact
Unauthorised access by anyone to session keys allowing them to change the lifespan.
Recommendation
We should check that the caller is a Smart wallet that initialised the Module as Hook.
