…/ethsnarks/depends/libsnark/depends/libff/libff/algebra/scalar_multiplication/multiexp.tcc:178:80 in …/loopring_v3/ethsnarks/depends/libsnark/depends/libff/libff/algebra/scalar_multiplication/multiexp.tcc:178:107: runtime error: shift exponent 64 is too large for 64-bit type 'unsigned long'
SUMMARY: UndefinedBehaviorSanitizer: undefined-behavior
…/ethsnarks/depends/libsnark/depends/libff/libff/algebra/scalar_multiplication/multiexp.tcc:178:107 in
----end of code block ----
Figure 11.1: UndefinedBehaviorSanitizer warnings
These warnings are caused by the following code:
----new code block----
static inline size_t get_id(size_t c, size_t bitno, const mp_limb_t* data)
{
 static const mp_limb_t one = 1;
 const mp_limb_t mask = (one << c) - one;
 const size_t limb_num_bits = sizeof(mp_limb_t) * 8;
 const size_t part = bitno / limb_num_bits;
 const size_t bit = bitno % limb_num_bits;
​
 size_t id = (data[part] & (mask << bit)) >> bit;
 // const mp_limb_t next_data = (bit + c >= limb_num_bits && part < 3) ? bn_exponents[i].data[part+1] : 0;
 // id |= (next_data & (mask >> (limb_num_bits - bit))) << (limb_num_bits - bit);
    id |= (((bit + c >= limb_num_bits && part < 3) ? data[part+1] : 0) & (mask >> (limb_num_bits - bit))) << (limb_num_bits - bit);
 return id;
}
----end of code block ----
Figure 11.2: get_id
Additionally, CodeQL identified potential integer overflows in the computations of
k*c
as arguments of
get_id
:
----new code block----
template<typename T, typename FieldT, bool with_density, bool prefetch, unsigned int prefetch_locality>
T multi_exp_inner_bellman_with_density(
    …
 unsigned int c,
 unsigned int k,
    …)
{
    …
 if (prefetch)
    {
 // prefetch next bucket
 if (i < length - look_ahead)
        {
 size_t next_id = get_id(c, k*c, &exponents[i+look_ahead].data[0]);
            …
        }
    }
 size_t id = get_id(c, k*c, &exponents[i].data[0]);
    …
}
----end of code block ----
Figure 11.3: Part of the multi_exp_inner_bellman_with_density function
The affected code was introduced by Loopring in a fork of
