Resolution
The issue was partially mitigated in
deposit
function by minting AToken before the transfer of the deposit token.
Description
Some tokens may allow users to perform re-entrancy while calling the
transferFrom
function. For example, it would be possible for an attacker to “borrow” a large amount of ERC-777 tokens from the lending pool by re-entering the
deposit
function from within
transferFrom
.
code/contracts/lendingpool/LendingPool.sol:L91-L118
----new code block----
function deposit(
 address asset,
 uint256 amount,
 address onBehalfOf,
 uint16 referralCode
) external override {
  \_whenNotPaused();
  ReserveLogic.ReserveData storage reserve = \_reserves[asset];
​
  ValidationLogic.validateDeposit(reserve, amount);
​
 address aToken = reserve.aTokenAddress;
​
  reserve.updateState();
  reserve.updateInterestRates(asset, aToken, amount, 0);
​
 bool isFirstDeposit = IAToken(aToken).balanceOf(onBehalfOf) == 0;
 if (isFirstDeposit) {
    \_usersConfig[onBehalfOf].setUsingAsCollateral(reserve.id, true);
  }
​
  IAToken(aToken).mint(onBehalfOf, amount, reserve.liquidityIndex);
​
 //transfer to the aToken contract
  IERC20(asset).safeTransferFrom(msg.sender, aToken, amount);
​
 emit Deposit(asset, msg.sender, onBehalfOf, amount, referralCode);
}
​
----end of code block ----
Because the
safeTransferFrom
call is happening at the end of the
deposit
function, the deposit will be fully processed before the tokens are actually transferred.
So at the beginning of the transfer, the attacker can re-enter the call to withdraw their deposit. The withdrawal will succeed even though the attacker’s tokens have not yet been transferred to the lending pool. Essentially, the attacker is granted a flash-loan but without paying fees.
Additionally, after these calls, interest rates will be skewed because interest rate update relies on the actual current balance.
Remediation
Do not whitelist ERC-777 or other re-entrable tokens to prevent this kind of attack.

Description
The reentrancy risk arises from the fact that the function performs a low-level call to the protocol contract using
protocolAddress.call
{value: msg.value}(...) without any reentrancy protection. If the called contract is malicious and attempts to re-enter the executeOperation function before the state changes are persisted, it can lead to unintended consequences.
----new code block----
​
 /// @notice execute approved operation
 /// @param opData 1
 /// @param transmitterSigs 2
 function executeOperation(
        OperationLib.OperationData calldata opData,
        Signature[] calldata transmitterSigs
    ) external payable isAllowedExecutor(opData.protocolAddr) {
 bytes32 msgHash = keccak256(
 abi.encodePacked(
                opData.protocolId,
                opData.meta,
                opData.srcChainId,
                opData.srcBlockNumber,
                opData.srcOpTxId,
                opData.nonce,
                opData.destChainId,
                opData.protocolAddr,
                opData.functionSelector,
                opData.params,
                opData.reserved
            )
        );
 bytes32 opHashBytes = keccak256(
 abi.encodePacked("\x19Ethereum Signed Message:\n32", msgHash)
        );
 uint256 opHash = uint256(opHashBytes);
​
 if (opData.destChainId != __chainId()) {
 revert Endpoint__OpIsNotForThisChain(opHash);
        }
​
 if (opExecutedMap[opHash]) {
 revert Endpoint__OpIsAlreadyExecuted(opHash);
        }
​
 address protocolAddress = abi.decode(opData.protocolAddr, (address));
 bytes32 protocolId = protocolAddressToProtocolId[protocolAddress];
​
 if (protocolId != opData.protocolId || allowedProtocolInfo[opData.protocolId].isCreated == false) {
 revert Endpoint__InvalidProtocolId(opData.protocolId);
        }
​
 address[] memory uniqSigners = new address[](transmitterSigs.length);
 uint uniqSignersCnt;
 bool consensusReached;
 uint numOfAllowedTransmitters = numberOfAllowedTransmitters[protocolId];
 if (numOfAllowedTransmitters == 0) {
 revert Endpoint__ZeroTransmittersCount(protocolId);
        }
 uint k;
 uint consensusTargetRate = allowedProtocolInfo[protocolId].consensusTargetRate;
 for (uint i; i < transmitterSigs.length; ) {
 address signer = ecrecover(
                opHashBytes,
                transmitterSigs[i].v,
                transmitterSigs[i].r,
                transmitterSigs[i].s
            );
 if (signer != address(0) && allowedTransmitters[protocolId][signer]) {
 bool isNewSigner = true;
 delete k;
 while (k < uniqSignersCnt) {
 if (uniqSigners[k] == signer) {
                        isNewSigner = false;
 break;
                    }
 unchecked {
 ++k;
                    }
                }
 if (isNewSigner) {
                    uniqSigners[uniqSignersCnt] = signer;
 ++uniqSignersCnt;
​
 uint256 consensusRate = (uniqSignersCnt * rateDecimals) /
                        numOfAllowedTransmitters;
 if (consensusRate >= consensusTargetRate) {
                        consensusReached = true;
 break;
                    }
                }
            }
 unchecked {
 ++i;
            }
        }
​
 if (consensusReached) {
            (uint8 selectorType, bytes memory selectorDecoded) = PhotonFunctionSelectorLib.decodeFunctionSelector(
                opData.functionSelector
            );
 assert(selectorType == uint8(PhotonFunctionSelectorLib.SelectorTypes.EVM));
 bytes4 selector = abi.decode(selectorDecoded, (bytes4));
            (bool success, bytes memory ret) = protocolAddress.call{value: msg.value}(
 abi.encodeWithSelector(
                    selector,
 abi.encode(
                        opData.protocolId,
                        opData.srcChainId,
                        opData.srcBlockNumber,
                        opData.srcOpTxId,
                        opData.params
                    )
                )
            );
​
 if (success) {
                opExecutedMap[opHash] = true;
            }
 // TODO: remove before mainnet
 else {
 revert Endpoint__TargetCallError(ret);
            }
 emit ProposalExecuted(opHash, success, ret);
        } else {
 revert Endpoint__OpIsNotApproved(opHash);
        }
    }
----end of code block ----
